insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('bfb30807-8423-5f62-a50c-fcd2d3e1e2ba', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', $gs$Have I recognized God’s common grace at work in the life of someone who does not yet know Christ?$gs$, 4),
  ('2c5f09c4-a5d8-5c3f-a9dc-5afc409b1659', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', $gs$How does understanding this distinction — common grace versus saving grace — clarify what someone still needs?$gs$, 5),
  ('073007c3-eb99-50e4-9a59-2ac6a1cb9b26', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', $gs$What genuine goodness have I observed in an unbeliever’s life that reflects God’s patient kindness?$gs$, 6),
  ('4d2ddb60-7fd4-509b-880d-4eb4d4922394', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', $gs$How might recognizing common grace help me approach unbelievers with greater warmth, not suspicion?$gs$, 7),
  ('ec18c91d-e309-599b-8f95-baf518c55743', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', $gs$Who in my life has experienced clear common grace, and how could I point them toward saving grace as well?$gs$, 8)
on conflict (id) do nothing;
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('431f405d-c775-5753-8aea-63b9e52a0947', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 'paragraph', $gs${"text":"Study question 1\n\nWhy does Jesus’s specific description — sun and rain given to both “evil” and “good” alike — reveal that God graciously extends genuine kindness to all people, including those still in their lost condition, not reserving His goodness exclusively for believers?\n\nJesus’s specific description reveals God’s genuine kindness extended to all, since sun and rain given to both evil and good establishes this comprehensive grace, meaning God graciously extends this kindness even to those in their lost condition, not reserving goodness exclusively for believers, but this passage’s specific description particularly requiring recognition of this common grace as genuine, though distinct from saving grace, throughout God’s ongoing dealing with all humanity."}$gs$::jsonb, 3, false, false),
  ('72646d51-558f-5d18-b68c-c5a4d7b062f6', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 'paragraph', $gs${"text":"Study question 2\n\nHow does recognizing this common grace help believers see even the genuine goodness, beauty, and blessing in an unbeliever’s life as evidence of God’s own, patient kindness rather than evidence that they need no genuine rescue?\n\nRecognizing common grace helps believers see genuine goodness as evidence of God’s patient kindness, since even unbelievers’ blessings flow from this gracious source, meaning believers should see this goodness as testimony to God’s patience, not evidence that rescue is unnecessary, but understanding this passage’s common grace as genuinely different from, though related to, the saving grace still needed by every person remaining in their lost condition."}$gs$::jsonb, 4, false, false),
  ('08a0ae2b-ce44-55d0-9d40-f2d120bf998c', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 'paragraph', $gs${"text":"Important Distinction\n\nRecognizing common grace does not mean unbelievers are therefore already right with God through their experience of His general kindness; common grace restrains evil and provides genuine blessing, but only saving grace, received through faith in Christ, actually reconciles a person to God."}$gs$::jsonb, 5, false, false),
  ('7a67decd-5f48-5a18-9f69-3eb0d3ca483c', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 'paragraph', $gs${"text":"Lesson Assignment\n\n1. Read Matthew 5:43-45 and reflect on God’s genuine kindness extended to all people.\n2. Identify a specific way you have seen common grace at work in an unbeliever’s life this week.\n3. Write about the distinction between common grace and saving grace in your own words.\n4. Discuss with your peer guide how recognizing common grace shapes their own approach to evangelism.\n5. Thank God specifically for a way His common grace has been evident in your own community."}$gs$::jsonb, 7, false, false),
  ('8425a522-5fe1-501d-b2be-5156798ca5c1', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 'reflection_question', $gs${"question":"Have I recognized God’s common grace at work in the life of someone who does not yet know Christ?"}$gs$::jsonb, 12, true, true),
  ('60296001-d9b0-56cb-b150-e9e122ea94cc', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 'reflection_question', $gs${"question":"How does understanding this distinction — common grace versus saving grace — clarify what someone still needs?"}$gs$::jsonb, 13, true, true),
  ('9d2bed2e-251a-5aa7-b9cd-920470633756', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 'reflection_question', $gs${"question":"What genuine goodness have I observed in an unbeliever’s life that reflects God’s patient kindness?"}$gs$::jsonb, 14, true, true),
  ('b68788c7-d02d-5ff9-afbe-b1f539147308', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 'reflection_question', $gs${"question":"How might recognizing common grace help me approach unbelievers with greater warmth, not suspicion?"}$gs$::jsonb, 15, true, true),
  ('a4e0b497-074b-579f-b0c8-e560625ed75a', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 'reflection_question', $gs${"question":"Who in my life has experienced clear common grace, and how could I point them toward saving grace as well?"}$gs$::jsonb, 16, true, true)
