insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('354c8071-9366-5166-ae17-8c7d5bbafdd0', '1a59347c-a73c-5050-ac93-6a902560464c', $gs$Have I ever assumed someone’s genuine salvation based merely on their outward, religious activity?$gs$, 4),
  ('2f26c43c-f67d-5c19-a63a-16dd13edcb4b', '1a59347c-a73c-5050-ac93-6a902560464c', $gs$Do I understand the difference between outward religious performance and genuine, inward regeneration?$gs$, 5),
  ('1d731288-2039-5be7-875b-cb7a19a29eab', '1a59347c-a73c-5050-ac93-6a902560464c', $gs$Have I ever mistaken my own religious activity for genuine relationship with Christ, at any point in my life?$gs$, 6),
  ('3a5724ae-30e2-5055-8923-d9bd649c14f5', '1a59347c-a73c-5050-ac93-6a902560464c', $gs$How could I gently, honestly explore this distinction with someone whose heart status seems unclear?$gs$, 7),
  ('2b196e51-1289-54b1-b1ec-a25755e41ebd', '1a59347c-a73c-5050-ac93-6a902560464c', $gs$What genuine evidence of regeneration, beyond mere activity, should I look for in my own life and others’?$gs$, 8)
on conflict (id) do nothing;
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('6e459811-74b3-5095-a4a7-7aedf5eb7b4d', '1a59347c-a73c-5050-ac93-6a902560464c', 'paragraph', $gs${"text":"Study question 1\n\nWhy does Jesus’s specific criticism — honoring with lips while the heart remains genuinely “far” — reveal that religious activity itself, without genuine regeneration, can leave a person’s actual, lost condition completely untouched and unaddressed?\n\nJesus’s specific criticism reveals religious activity’s potential insufficiency, since honoring with lips while the heart stays far establishes this genuine disconnect, meaning religious activity itself, without genuine regeneration, can leave the lost condition entirely unaddressed, but this passage’s specific criticism particularly requiring recognition that outward religious performance never substitutes for the genuine, inward transformation only regeneration provides throughout a person’s actual, spiritual condition and standing before God."}$gs$::jsonb, 3, false, false),
  ('33727dfe-437c-5cd2-a746-13d8f111321c', '1a59347c-a73c-5050-ac93-6a902560464c', 'paragraph', $gs${"text":"Study question 2\n\nHow does understanding this distinction help believers discern when someone’s religious activity, however sincere or extensive, may still leave them genuinely unconverted, requiring gentle, honest gospel conversation rather than assumed spiritual safety based on outward practice alone?\n\nUnderstanding this distinction helps discern genuine unconversion despite religious activity, since sincere religious practice does not guarantee genuine regeneration, meaning believers should discern this possibility gently and honestly, not assuming spiritual safety based on outward practice alone, but pursuing this passage’s called-for discernment throughout their gospel conversation with religiously active, yet possibly unconverted, individuals."}$gs$::jsonb, 4, false, false),
  ('2e793965-4628-55dd-a1d2-5669df54a9ea', '1a59347c-a73c-5050-ac93-6a902560464c', 'paragraph', $gs${"text":"Important Distinction\n\nRecognizing this danger does not mean judging every religiously active person as unconverted; it means genuine gospel conversation, not assumption either way, is warranted whenever someone’s actual, inward relationship with Christ remains unclear."}$gs$::jsonb, 5, false, false),
  ('93936d85-4446-5aaf-8ba9-d53bd225369d', '1a59347c-a73c-5050-ac93-6a902560464c', 'paragraph', $gs${"text":"Lesson Assignment\n\n1. Read Matthew 15:7-9 and reflect on the danger of outward religion without genuine, inward regeneration.\n2. Identify a specific, gentle way to explore this distinction with someone whose spiritual status seems unclear.\n3. Examine your own life honestly for any area where activity has substituted for genuine relationship.\n4. Discuss with your peer guide how they discern this distinction with wisdom and grace, not harsh judgment.\n5. Pray for discernment and gentleness as you navigate these conversations with religiously active people."}$gs$::jsonb, 7, false, false),
  ('cf241030-ad9d-508e-b9d1-36cddfbf04e1', '1a59347c-a73c-5050-ac93-6a902560464c', 'reflection_question', $gs${"question":"Have I ever assumed someone’s genuine salvation based merely on their outward, religious activity?"}$gs$::jsonb, 12, true, true),
  ('58443faa-d143-532a-be9a-c8aae2d1d7d8', '1a59347c-a73c-5050-ac93-6a902560464c', 'reflection_question', $gs${"question":"Do I understand the difference between outward religious performance and genuine, inward regeneration?"}$gs$::jsonb, 13, true, true),
  ('6ff7044a-9fbf-5200-8252-967fafecd58c', '1a59347c-a73c-5050-ac93-6a902560464c', 'reflection_question', $gs${"question":"Have I ever mistaken my own religious activity for genuine relationship with Christ, at any point in my life?"}$gs$::jsonb, 14, true, true),
  ('f992cf99-5503-5634-9f8c-d4ef6b06e4b9', '1a59347c-a73c-5050-ac93-6a902560464c', 'reflection_question', $gs${"question":"How could I gently, honestly explore this distinction with someone whose heart status seems unclear?"}$gs$::jsonb, 15, true, true),
  ('08a1f809-dd58-50bc-8c84-eaf01f60bcf7', '1a59347c-a73c-5050-ac93-6a902560464c', 'reflection_question', $gs${"question":"What genuine evidence of regeneration, beyond mere activity, should I look for in my own life and others’?"}$gs$::jsonb, 16, true, true)
