  ('188d60ae-2208-5bbd-801b-0eb0e8babab2', '5db4bc9a-62a0-5bb2-b28b-852fcf0011d2', 'paragraph', $gs${"text":"Lesson Assignment\n\n1. Read Romans 10:1-4 and reflect on Paul’s own, genuine, ongoing prayer for the unsaved.\n2. Write down the names of three specific, unsaved people in your life.\n3. Commit to praying for these three people by name, consistently, over the next month.\n4. Discuss with your peer guide how sustained prayer has shaped their own evangelism and compassion.\n5. Journal about any changes in your own heart toward these specific people as you continue this practice."}$gs$::jsonb, 7, false, false),
  ('ab872e95-d3f2-59e5-a3f5-d291d18cbfc8', '5db4bc9a-62a0-5bb2-b28b-852fcf0011d2', 'reflection_question', $gs${"question":"Do I currently pray specifically, by name, for the unsaved people in my life, or does my concern remain vague?"}$gs$::jsonb, 12, true, true),
  ('42bebc3d-adea-5c6d-b871-470f2033fe63', '5db4bc9a-62a0-5bb2-b28b-852fcf0011d2', 'reflection_question', $gs${"question":"What would it look like to develop Paul’s own kind of consistent, genuine “heart’s desire and prayer” for someone?"}$gs$::jsonb, 13, true, true),
  ('4879e17d-c3ae-59c1-8fa5-48bd9962c513', '5db4bc9a-62a0-5bb2-b28b-852fcf0011d2', 'reflection_question', $gs${"question":"Who are three specific, unsaved people I could commit to praying for regularly over the coming months?"}$gs$::jsonb, 14, true, true),
  ('eee7f1d1-615c-5b2d-839b-235e1127d1f6', '5db4bc9a-62a0-5bb2-b28b-852fcf0011d2', 'reflection_question', $gs${"question":"How might sustained, specific prayer change my own heart and readiness to actually speak with these people?"}$gs$::jsonb, 15, true, true),
  ('a283b528-6a81-5378-874a-3dc5e738f0c2', '5db4bc9a-62a0-5bb2-b28b-852fcf0011d2', 'reflection_question', $gs${"question":"What has prevented me from praying as consistently as I know I genuinely should for the lost?"}$gs$::jsonb, 16, true, true)
