  ('f2ca4de4-9bf3-556f-8d7d-63a3965858ae', 'ab7f90f7-bff8-54d2-9c04-c7114e4b658d', 'reflection_question', $gs${"question":"What hope do I draw from the promise that my own resurrection will follow this same, “firstfruits” pattern?"}$gs$::jsonb, 14, true, true),
