insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('04bda0f8-0274-5a47-9d25-460d52829e02', '2d56ae11-0460-5105-a475-bcb7211420d3', $gs$Have I admired Christ’s teaching from a comfortable distance without genuinely following Him wholly?$gs$, 4),
  ('c257d60f-299a-5fc3-9cc9-d6925094f89b', '2d56ae11-0460-5105-a475-bcb7211420d3', $gs$What specific area of self-denial does this passage’s instruction bring to mind for my own life right now?$gs$, 5),
  ('0e270b67-79f1-597d-8c22-a69f1bc3753c', '2d56ae11-0460-5105-a475-bcb7211420d3', $gs$How does everything I’ve learned throughout this plan about Christ’s person and work shape my willingness to follow Him?$gs$, 6),
  ('16fde3df-c875-5be3-8132-a6abb21211f5', '2d56ae11-0460-5105-a475-bcb7211420d3', $gs$What would wholehearted, costly following look like practically in my current circumstances?$gs$, 7),
  ('5f269034-e670-57e5-af26-ed64bf35eec8', '2d56ae11-0460-5105-a475-bcb7211420d3', $gs$How can I hold genuine grace for my incomplete discipleship while still pursuing this ongoing, wholehearted following?$gs$, 8)
on conflict (id) do nothing;
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('c39d2560-9c16-5a3f-8f95-e1eafc78939c', '2d56ae11-0460-5105-a475-bcb7211420d3', 'paragraph', $gs${"text":"Study question 1\n\nWhy does Jesus’s specific instruction — genuine self-denial and cross-bearing — reveal that following Him wholly requires comprehensive, costly commitment, not merely admiring His teaching from a comfortable, unaffected distance?\n\nJesus’s specific instruction reveals comprehensive, costly commitment, since genuine self-denial and cross-bearing establish this necessary cost, meaning following Christ wholly requires this comprehensive commitment, not merely admiring His teaching from a distance, but this passage’s specific instruction particularly requiring this costly, genuine following as characteristic of authentic discipleship throughout believers’ ongoing relationship with and response to who Christ genuinely is and requires."}$gs$::jsonb, 3, false, false),
  ('c3114ca9-8b2c-5044-87c1-94f99a611cf3', '2d56ae11-0460-5105-a475-bcb7211420d3', 'paragraph', $gs${"text":"Study question 2\n\nHow does this comprehensive following flow naturally from everything this plan has explored — His genuine person, completed work, and rightful titles — rather than representing an additional, separate requirement disconnected from genuine understanding of who Christ actually is?\n\nThis comprehensive following flows naturally from everything explored, since genuine understanding naturally produces this response, not a separate requirement, meaning wholehearted discipleship represents the natural, appropriate response to genuinely understanding Christ’s person and work, not remaining a disconnected, additional requirement, but flowing from this passage’s called-for following as appropriate response throughout believers’ comprehensive, genuine relationship with Christ as Savior, Lord, and coming King."}$gs$::jsonb, 4, false, false),
  ('01228c8b-7b88-5dbb-a5b3-eeadd2f665c6', '2d56ae11-0460-5105-a475-bcb7211420d3', 'paragraph', $gs${"text":"Important Distinction\n\nFollowing Christ wholly does not mean achieving flawless, complete discipleship from the outset; it means a genuine, ongoing direction and posture of following, even while continued growth, struggle, and dependence on grace remain part of this lifelong journey."}$gs$::jsonb, 5, false, false),
  ('9f577dd4-271a-5fce-b875-b850c86597f4', '2d56ae11-0460-5105-a475-bcb7211420d3', 'paragraph', $gs${"text":"Lesson Assignment\n\n1. Read Matthew 16:24-26 and reflect on the genuine cost of wholehearted discipleship.\n2. Identify one specific area of self-denial you sense Christ is calling you toward right now.\n3. Take a concrete step in this specific area this week, trusting Christ’s grace throughout the process.\n4. Discuss with your peer guide how they have grown in wholehearted following over their own journey.\n5. Journal about your own, ongoing commitment to follow Christ wholly, not merely admire Him from a distance."}$gs$::jsonb, 7, false, false),
  ('6242e409-917f-50c9-925d-59136b1a9aa2', '2d56ae11-0460-5105-a475-bcb7211420d3', 'reflection_question', $gs${"question":"Have I admired Christ’s teaching from a comfortable distance without genuinely following Him wholly?"}$gs$::jsonb, 12, true, true),
  ('f8a6a917-eeb2-5ac5-9791-b37a2ea1550a', '2d56ae11-0460-5105-a475-bcb7211420d3', 'reflection_question', $gs${"question":"What specific area of self-denial does this passage’s instruction bring to mind for my own life right now?"}$gs$::jsonb, 13, true, true),
  ('2eab87a8-fd8d-5065-9d08-a4a2e23223f3', '2d56ae11-0460-5105-a475-bcb7211420d3', 'reflection_question', $gs${"question":"How does everything I’ve learned throughout this plan about Christ’s person and work shape my willingness to follow Him?"}$gs$::jsonb, 14, true, true),
  ('fa8cddc1-6feb-548b-ab0b-bcb2d4b1908a', '2d56ae11-0460-5105-a475-bcb7211420d3', 'reflection_question', $gs${"question":"What would wholehearted, costly following look like practically in my current circumstances?"}$gs$::jsonb, 15, true, true),
  ('52084dcc-deae-5fcb-8666-f222e2e372ca', '2d56ae11-0460-5105-a475-bcb7211420d3', 'reflection_question', $gs${"question":"How can I hold genuine grace for my incomplete discipleship while still pursuing this ongoing, wholehearted following?"}$gs$::jsonb, 16, true, true)
on conflict (id) do nothing;
