update public.p2p_lesson_sections set section_order = 21 where id = '6cc703fd-5b44-52c4-b13a-423c00969af8' and section_order <> 21;
update public.p2p_lesson_sections set section_order = 24 where id = 'e79a2b88-1180-594f-a413-584d36fb909b' and section_order <> 24;
insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('a87acde3-1fe6-580a-8ec8-cee47586536f', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', $gs$Have I unconsciously assumed certain people are beyond the gospel’s genuine reach, based on their history or reputation?$gs$, 4),
  ('8e98991b-253f-592a-9eb1-c7f2e6e7a7cd', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', $gs$How does this passage’s comprehensive promise challenge and correct any such assumption I have held?$gs$, 5),
  ('ce0184d1-6eb4-5878-9b17-3ad9c6e441b8', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', $gs$Who in my life have I perhaps written off as unreachable, whom this passage’s promise still genuinely includes?$gs$, 6),
  ('75882768-b3ff-58af-b9ef-11e343cd70b7', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', $gs$How does this universal promise motivate greater hope and boldness in my own evangelism?$gs$, 7),
  ('38420166-efc3-5fa6-90b8-3ed2b534378a', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', $gs$What would it look like to approach this specific person with renewed, genuine hope this week?$gs$, 8),
  ('1fd46c7c-f5a0-5cb3-ae96-cb21830807ef', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', $gs$Why is the gospel intended for people from every nation and background?$gs$, 9),
  ('69606d5a-e937-522f-aba2-9634b7a38c19', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', $gs$What does the story of Zacchaeus teach about Jesus' willingness to reach rejected people?$gs$, 10),
  ('b78dba6f-724e-5fdd-a43b-2b8d07c4b56e', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', $gs$How did Jesus cross cultural and social boundaries in His meeting with the Samaritan woman?$gs$, 11),
  ('7df94121-8367-5c8e-87b2-b07d392057f2', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', $gs$How does Paul's story encourage people who feel ashamed of their past?$gs$, 12),
  ('687a6c10-74e1-5a7b-8fc7-423a06b2d436', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', $gs$Why do both religious and irreligious people need the gospel?$gs$, 13),
  ('9adc04fe-7e79-5889-a071-064cf2df5daa', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', $gs$What does it mean that God shows no partiality?$gs$, 14),
  ('9dca62a6-6f9e-5190-abad-5c25e8b30d0e', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', $gs$Have you ever judged someone as unlikely to respond to the gospel? What does Scripture teach you about that attitude?$gs$, 15),
  ('e60443d7-762d-55d4-a6ee-68842459de5c', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', $gs$Who in your life needs to hear the good news of Jesus?$gs$, 16),
  ('ed236654-5b19-587c-b217-0f38ff2cbde1', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', $gs$What practical step can you take to show compassion and share the gospel with that person?$gs$, 17)
on conflict (id) do nothing;
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('938cf3a8-ddb6-5b92-a4dc-34b2f778a384', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"About this module\n\nThe gospel is God's message of salvation through Jesus Christ, and it is intended for people from every nation, culture, background, and walk of life. No person is beyond the reach of God's mercy, and no person is so good that they do not need the gospel.\n\nJesus did not come into the world to save only a particular social group, nationality, or type of person. He came to save sinners. His invitation is extended to all people, and everyone is called to repent and believe in Him.\n\nThis module teaches that the gospel is not limited by a person's past, education, wealth, family background, social position, or religious history. It also explains that the gospel places everyone on the same level before God. Every person is a sinner who needs grace, and every person who is saved is saved through the same Saviour.\n\nThe module also addresses an important truth: the gospel is not only something people need to hear when they first become Christians. It remains the foundation of the entire Christian life. Believers continue to need its truth every day. They grow in their understanding of Christ's love, depend on His grace, and learn to live in the light of what He has accomplished."}$gs$::jsonb, 1, false, false),
  ('5b2a3a2f-ea03-5492-91cc-839049c6cf03', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"Main Scripture references\n\n• Genesis 12:1–3\n• Isaiah 49:5–6\n• Matthew 11:28–30\n• Matthew 28:18–20\n• Luke 19:1–10\n• John 3:16–17\n• John 4:1–42\n• Acts 10:34–43\n• Acts 17:30–31\n• Romans 1:16–17\n• Romans 3:9–24\n• Romans 10:9–17\n• Galatians 3:26–29\n• Ephesians 2:11–22\n• 1 Timothy 1:12–16\n• 1 Timothy 2:1–6\n• Revelation 5:9–10"}$gs$::jsonb, 2, false, false),
  ('7f1374e4-11fc-5421-b3ba-ac9f9539e839', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"Module objectives\n\nBy the end of this module, learners should be able to:\n\n1. Explain why the gospel is offered to people from every background.\n2. Understand that no person's past is greater than God's ability to save.\n3. Recognise that every person needs salvation, regardless of their social or religious position.\n4. Understand that salvation is received through the same Lord and by the same grace.\n5. Explain why the gospel should be shared without favouritism or discrimination.\n6. Understand that the gospel remains central throughout the Christian life.\n7. Develop a compassionate attitude toward people who have not yet believed in Christ."}$gs$::jsonb, 3, false, false),
  ('5c4b09cc-a9a3-54bf-a9b4-7689c4b94d1c', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"Main Scriptures\n\nJohn 3:16–17; Luke 19:1–10; John 4:1–42; Romans 10:9–13; 1 Timothy 1:12–16; Acts 10:34–43."}$gs$::jsonb, 6, false, false),
  ('91f36be8-dfca-54bf-b6d9-5cb9fed7db49', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"Introduction\n\nOne of the most encouraging truths of the gospel is that no person is beyond the reach of God's saving grace. People may have very different histories. Some have lived respectable lives, while others have been involved in serious wrongdoing. Some have grown up in Christian homes, while others have never heard the message of Jesus. Some are wealthy and educated, while others are poor and have little formal education.\n\nYet every person needs the same Saviour, and the same gospel is offered to all.\n\nPeople sometimes assume that certain individuals are too sinful to be forgiven. They may look at someone's past and conclude that such a person could never change. Others may believe that they themselves are too damaged, too guilty, or too far away from God to be accepted.\n\nThe gospel challenges both ways of thinking. It does not say that sin is unimportant or that people can remain unchanged. It says that Jesus Christ came to save sinners and that His saving power is greater than the guilt and shame of their past.\n\nThis lesson will help us understand that the invitation of the gospel is wide, the mercy of God is great, and the church must never decide that someone is beyond hope."}$gs$::jsonb, 7, false, false),
  ('72c9a445-2883-5509-9555-1b2827a5c99e', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"1. God's Saving Purpose Has Always Included the Nations\n\nScripture: Genesis 12:1–3; Isaiah 49:5–6\n\nGod's plan to bless the nations did not begin in the New Testament. From the beginning of His dealings with humanity, He revealed that His saving purpose would reach beyond one family or nation.\n\nIn Genesis 12, God called Abraham and promised that through him all the families of the earth would be blessed. Abraham's calling was not simply about giving him a special personal future. God was beginning a plan through which blessing would eventually reach people throughout the world.\n\nLater, Isaiah spoke about God's servant being a light to the nations so that salvation would reach the ends of the earth. This pointed forward to the coming of Christ and the worldwide reach of His saving work.\n\nJesus came into the world as the promised Saviour through whom God's blessing would be offered to all peoples. His death and resurrection opened the way for people from every nation to become part of God's people through faith.\n\nThis means the gospel should never be treated as the possession of one culture, language, or nationality. The message belongs to the whole world because Jesus is Lord over all.\n\nThe church must therefore have a worldwide outlook. It should care about people who are different from its members and should be willing to take the gospel across cultural and social boundaries."}$gs$::jsonb, 8, false, false),
  ('4d22683d-d862-5656-b1c0-81e438cbc678', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"2. God's Love Is Offered to the World\n\nScripture: John 3:16–17; 1 John 4:9–10\n\nJohn 3:16 declares that God loved the world and gave His only Son so that whoever believes in Him should not perish but have eternal life.\n\nThe word \"whoever\" is important. It shows that the invitation is not restricted to a small group of people based on their background or achievements.\n\nGod's love is not limited to those who appear respectable. He calls sinners to come to Christ and receive life.\n\nThis does not mean every person is automatically saved. John 3 also makes clear that people must believe in the Son. The invitation is wide, but the response of faith matters.\n\nGod sent His Son because the world needed rescue. Jesus did not come merely to improve human society or provide a better example of moral behaviour. He came to save people from sin and its consequences.\n\nThe gospel therefore offers hope to people who know they need forgiveness. It also challenges people who think they are already good enough without Christ.\n\nWhen we share the gospel, we should not decide in advance who is likely to believe. Our responsibility is to communicate the truth faithfully and invite people to respond to Jesus."}$gs$::jsonb, 9, false, false),
  ('ca5f0689-2d98-5f00-b045-26c8689064b0', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"3. Jesus Welcomed People Others Rejected\n\nScripture: Luke 19:1–10; Mark 2:13–17\n\nDuring His earthly ministry, Jesus regularly spent time with people whom others looked down upon.\n\nIn Luke 19, we read about Zacchaeus, a chief tax collector. Tax collectors were often hated because they worked within the Roman system and could use their position to take more money from people than was required.\n\nZacchaeus was wealthy, but his wealth did not mean that he was right with God. He was also socially rejected because of his occupation.\n\nWhen Jesus passed through Jericho, Zacchaeus climbed a tree to see Him. Jesus stopped, called him by name, and told him that He would stay at his house.\n\nThe crowd complained because Jesus had chosen to visit a man they regarded as a sinner. But Jesus explained that He had come to seek and save the lost.\n\nZacchaeus responded to Jesus with a changed attitude toward money and wrongdoing. He promised to give to the poor and repay those he had cheated.\n\nHis response showed that meeting Jesus had affected his life. Jesus did not approve of Zacchaeus's dishonest behaviour, but neither did He treat him as beyond hope.\n\nThis account teaches us that people should not be rejected simply because of their past. Jesus knows the truth about every person, and He is able to bring real change.\n\nThe church must learn from His example. It should not make people feel that they must first repair every part of their lives before they are allowed to hear the gospel. They need to hear the gospel because they need Christ."}$gs$::jsonb, 10, false, false),
  ('32af6b3c-f7e1-5c66-b854-6d97d4f755b8', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"4. Jesus Crossed Social and Cultural Boundaries\n\nScripture: John 4:1–42\n\nIn John 4, Jesus met a Samaritan woman at a well. This encounter was significant because Jews and Samaritans had a history of hostility and division.\n\nThere were also social expectations surrounding men and women speaking publicly. Yet Jesus began a conversation with her and spoke about the living water that He could give.\n\nThe woman had a complicated personal history. Jesus knew about her previous marriages and her present relationship. He did not need someone else to tell Him about her life.\n\nYet He spoke to her with seriousness and dignity. He revealed spiritual truth to her and made clear that He was the promised Messiah.\n\nThe woman responded by telling others about Jesus. Many Samaritans came to hear Him, and many believed.\n\nThis account teaches several important lessons.\n\nFirst, the gospel crosses barriers that people have created. Jesus did not allow cultural hostility to prevent Him from speaking to someone who needed the truth.\n\nSecond, Jesus knows people's lives completely. Nothing about a person's past is hidden from Him.\n\nThird, a difficult history does not prevent someone from becoming a witness for Christ. The woman who came to the well with her own questions became someone who invited others to meet Jesus.\n\nChristians must therefore be willing to speak with people who are different from them. We should not allow prejudice, fear, or social discomfort to keep us from showing the love of Christ."}$gs$::jsonb, 11, false, false),
  ('248ea3c7-8374-5467-838a-bee4dba2270b', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"5. The Gospel Can Reach People With a Troubled Past\n\nScripture: 1 Timothy 1:12–16; Acts 9:1–22\n\nSome people struggle to believe that God could forgive them because of what they have done.\n\nThey may carry memories of dishonesty, violence, sexual wrongdoing, addiction, cruelty, or other serious sins. They may believe that their past has permanently disqualified them from receiving God's mercy.\n\nThe apostle Paul provides a powerful example of God's ability to save a person with a deeply troubled past.\n\nBefore becoming a follower of Christ, Paul persecuted the church. He opposed Christians and supported actions against them. He believed he was serving God, but he was actually fighting against the work of Jesus.\n\nYet Christ met him and transformed his life.\n\nIn 1 Timothy 1, Paul describes himself as someone who had been a blasphemer, persecutor, and violent man. He explains that he received mercy and that Christ's patience was displayed through his salvation.\n\nPaul did not pretend that his former actions were acceptable. He recognised the seriousness of what he had done. But he also recognised that God's grace was greater than his past.\n\nHis story reminds us that no sinner should conclude that forgiveness is impossible. The power to save belongs to Christ.\n\nAt the same time, we must understand that receiving forgiveness does not remove every earthly consequence of past actions. A person may still need to make restitution, face legal responsibilities, rebuild broken relationships, or accept wise boundaries. Grace does not mean pretending that harm never happened. It means that sin does not have to remain the final word over a person's relationship with God."}$gs$::jsonb, 12, false, false),
  ('41640b69-eb65-5b40-9eea-295cb56500f5', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"6. The Gospel Is for Religious and Irreligious People\n\nScripture: Luke 18:9–14; Romans 10:1–4\n\nPeople can be far from God in different ways.\n\nSome openly reject God and live without concern for His commands. Others are religious, attend worship services, know Scripture, and perform religious activities. Yet religious activity does not automatically mean a person has been reconciled to God.\n\nIn Luke 18, Jesus tells a story about a Pharisee and a tax collector who went to the temple to pray.\n\nThe Pharisee trusted in his own religious behaviour. He compared himself with others and considered himself superior. The tax collector, however, recognised his guilt and asked God for mercy.\n\nJesus said that the tax collector went home justified rather than the Pharisee.\n\nThe lesson is not that religious practices are always wrong. Prayer, worship, Scripture, and obedience are important. The problem is trusting in these activities as the basis of our acceptance before God.\n\nA person who openly rejects religion needs the gospel because of sin. A person who is deeply religious also needs the gospel if they are trusting in their own performance rather than Christ.\n\nNo one is saved by being irreligious, and no one is saved by religious activity alone. Salvation comes through Jesus Christ."}$gs$::jsonb, 13, false, false),
  ('e06d153a-c541-5eee-a5c0-806b0e257733', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"7. God Shows No Favouritism\n\nScripture: Acts 10:34–43; Romans 2:11\n\nIn Acts 10, Peter visits the home of Cornelius, a Gentile who was seeking God. This was an important moment because Peter had to recognise that the gospel was not limited to the Jewish people.\n\nPeter declared that God shows no partiality but welcomes people from every nation who fear Him and do what is right.\n\nThis does not mean that people earn salvation by their good behaviour. The passage goes on to proclaim Jesus Christ, His death, His resurrection, and the forgiveness of sins through His name.\n\nPeter had to learn that he could not place cultural boundaries around God's saving message.\n\nThe same lesson applies to the church today. We must not treat people as more or less deserving of the gospel because of their nationality, race, education, wealth, occupation, or social standing.\n\nGod does not measure people by the standards that human societies often use. Everyone stands accountable before Him, and everyone needs the grace provided through Christ."}$gs$::jsonb, 14, false, false),
  ('a22558c0-4257-5684-821d-812fe89c874c', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"8. The Gospel Is Powerful Enough to Save\n\nScripture: Romans 1:16–17; Romans 10:9–13\n\nPaul describes the gospel as the power of God for salvation to everyone who believes.\n\nThe gospel is not powerful because the person sharing it is especially talented or persuasive. Its power comes from God and the saving work of Jesus Christ.\n\nThis should give Christians confidence when sharing the message. They may not have perfect speaking skills or the ability to answer every question. They may feel nervous or inadequate. But they can trust that God is able to use His Word.\n\nRomans 10 teaches that everyone who calls on the name of the Lord will be saved. This invitation is not restricted to one nation or social group.\n\nThe gospel calls people to turn from sin and trust in Christ. It offers forgiveness and new life through Him.\n\nWe must never underestimate what God can do through the message of the cross and resurrection. A person who seems uninterested today may become a believer later. Someone who appears hardened may be deeply affected by the truth of Scripture.\n\nOur responsibility is to speak faithfully, pray sincerely, and trust God with the results."}$gs$::jsonb, 15, false, false),
  ('e45f6c1c-b786-5c64-a003-1a904231a4b5', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"9. A Person's Past Does Not Have to Define Their Future\n\nScripture: 2 Corinthians 5:17; 1 Corinthians 6:9–11\n\nWhen someone comes to Christ, they receive a new identity.\n\nSecond Corinthians 5:17 teaches that anyone who is in Christ is a new creation. The old has passed away, and the new has come.\n\nThis does not mean that the person loses all memories or that every struggle disappears immediately. It means that their relationship with God has changed and that a new life has begun.\n\nFirst Corinthians 6 describes people who had lived in various forms of sin. Paul then reminds them that they had been washed, sanctified, and justified in the name of the Lord Jesus Christ and by the Spirit of God.\n\nTheir past was real, but it was no longer the defining truth about their standing before God.\n\nThe same hope is available today. People do not need to remain trapped in the identity of their former life. Through Christ, they can be forgiven and begin to live in a new direction.\n\nThis should encourage us to see people in the light of what God can do, not only in the light of what they have done."}$gs$::jsonb, 16, false, false),
  ('716170aa-1d7d-5995-9083-bcd930aad3f4', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"10. The Church Must Carry the Gospel to Everyone\n\nScripture: Matthew 28:18–20; Acts 1:8; Revelation 5:9–10\n\nJesus commanded His followers to make disciples of all nations. This command shows that the gospel is intended to reach the whole world.\n\nThe church is not called to keep the message within its own walls. It is called to make Christ known through preaching, teaching, personal witness, service, and the formation of disciples.\n\nActs 1:8 describes the disciples receiving power from the Holy Spirit to be witnesses from their local surroundings to the ends of the earth.\n\nRevelation 5 gives a picture of people from every tribe, language, people, and nation worshipping the Lamb. This reminds us that God's saving purpose reaches across the boundaries that divide humanity.\n\nEvery believer has a part in this mission. Some may travel to other nations, while others share the gospel with neighbours, relatives, friends, colleagues, and people in their communities.\n\nThe important thing is that we do not decide that certain people are not worth reaching. Christ calls His church to make the gospel known to everyone."}$gs$::jsonb, 17, false, false),
  ('1332b4ac-f13a-5cce-84e3-8804531b93e6', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"Study question 1\n\nWhy does Paul’s specific, comprehensive promise — “whoever” calls, without exception — reveal that the gospel’s reach genuinely extends to every person, regardless of their specific background, history, or perceived unworthiness?\n\nPaul’s specific, comprehensive promise reveals the gospel’s universal reach, since “whoever,” without exception, establishes this comprehensive scope, meaning the gospel genuinely extends to every person regardless of background or perceived unworthiness, but this passage’s specific promise particularly requiring recognition of this universal, comprehensive reach as characteristic of the gospel’s genuine, biblical scope throughout believers’ understanding of who this good news genuinely addresses."}$gs$::jsonb, 18, false, false),
  ('2d4243dd-4cf3-51f1-92be-17c0ff5eff07', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"Study question 2\n\nHow does this universal promise challenge believers who might unconsciously assume certain people — based on their history, lifestyle, or reputation — are somehow beyond the gospel’s genuine reach, requiring correction toward this passage’s comprehensive, unqualified promise?\n\nThis universal promise challenges unconscious assumptions of exclusion, since assumed exclusion contradicts this comprehensive, unqualified promise, meaning believers holding such assumptions require correction toward this passage’s genuine, comprehensive scope, not limiting the gospel based on someone’s history or reputation, but embracing this passage’s called-for, universal confidence throughout their evangelism and genuine hope for every person they encounter."}$gs$::jsonb, 19, false, false),
  ('6cea0650-c972-5244-8131-301847d017c8', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"Important Distinction\n\nAffirming the gospel’s universal reach does not mean every person will respond positively; it means no genuine barrier of background, history, or reputation exists on God’s side that would prevent someone from receiving this gospel if they genuinely call on Him."}$gs$::jsonb, 20, false, false),
  ('87a028e3-d20e-53a0-848b-ed772d6c40ed', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"Lesson Summary\n\nThe gospel is for people from every nation, culture, and background. Jesus welcomed people who were rejected by society, crossed cultural boundaries, and offered hope to sinners. The stories of Zacchaeus, the Samaritan woman, Paul, and Cornelius show that God's saving grace reaches people with very different histories. No one should be treated as beyond hope, and no one should be considered too good to need Christ. The church is called to carry the gospel to everyone."}$gs$::jsonb, 22, false, false),
  ('a69b7669-6bb6-5777-b573-6879976f3a2a', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'paragraph', $gs${"text":"Lesson Assignment\n\n1. Read Romans 10:11-13 and reflect on the gospel’s comprehensive, unqualified reach.\n2. Identify someone you may have unconsciously written off, and pray for renewed hope regarding them.\n3. Take a small step toward reengaging this person with genuine, gospel-centered hope.\n4. Discuss with your peer guide how they maintain hope for people who seem far from God.\n5. Journal about your own growth in believing no one is genuinely beyond the gospel’s reach."}$gs$::jsonb, 23, false, false),
  ('444ef2fe-14a1-5b31-bc26-3213473e0aa5', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'reflection_question', $gs${"question":"Have I unconsciously assumed certain people are beyond the gospel’s genuine reach, based on their history or reputation?"}$gs$::jsonb, 28, true, true),
  ('5a54dc8c-e177-5db2-9c68-04adf7f43135', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'reflection_question', $gs${"question":"How does this passage’s comprehensive promise challenge and correct any such assumption I have held?"}$gs$::jsonb, 29, true, true),
  ('b1a30cdf-9ddf-5031-876f-6ebc0f2d1e76', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'reflection_question', $gs${"question":"Who in my life have I perhaps written off as unreachable, whom this passage’s promise still genuinely includes?"}$gs$::jsonb, 30, true, true),
  ('12d1627a-57b6-5123-a332-56a11d46342e', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'reflection_question', $gs${"question":"How does this universal promise motivate greater hope and boldness in my own evangelism?"}$gs$::jsonb, 31, true, true),
  ('3244bdad-a058-5ddb-bdd1-054e6eadabba', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'reflection_question', $gs${"question":"What would it look like to approach this specific person with renewed, genuine hope this week?"}$gs$::jsonb, 32, true, true),
  ('508b3e23-8f40-5e42-9b14-ebffcc3e0330', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'reflection_question', $gs${"question":"Why is the gospel intended for people from every nation and background?"}$gs$::jsonb, 33, true, true),
  ('c8b80ece-fe4c-5270-9610-959904c06e78', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'reflection_question', $gs${"question":"What does the story of Zacchaeus teach about Jesus' willingness to reach rejected people?"}$gs$::jsonb, 34, true, true),
  ('0f9808d7-6216-53e4-ac9a-54bc23037a00', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'reflection_question', $gs${"question":"How did Jesus cross cultural and social boundaries in His meeting with the Samaritan woman?"}$gs$::jsonb, 35, true, true),
  ('173ae3b2-c007-57af-b461-cc4d6d93c472', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'reflection_question', $gs${"question":"How does Paul's story encourage people who feel ashamed of their past?"}$gs$::jsonb, 36, true, true),
  ('f51864fc-6349-52e0-aae0-2b9333e74d6e', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'reflection_question', $gs${"question":"Why do both religious and irreligious people need the gospel?"}$gs$::jsonb, 37, true, true),
  ('ab338b78-3e96-5eff-9d92-8aaa90ebdaee', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'reflection_question', $gs${"question":"What does it mean that God shows no partiality?"}$gs$::jsonb, 38, true, true),
  ('c24c36d7-e180-5dcd-b332-9e6e26ee0f41', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'reflection_question', $gs${"question":"Have you ever judged someone as unlikely to respond to the gospel? What does Scripture teach you about that attitude?"}$gs$::jsonb, 39, true, true),
  ('4da6f726-08c5-5c18-bf3f-3e308404dc66', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'reflection_question', $gs${"question":"Who in your life needs to hear the good news of Jesus?"}$gs$::jsonb, 40, true, true),
  ('0f25e9ef-0bb4-50bf-8b40-fa499d049983', 'cd2d889b-f0ea-5d4c-9829-1e94976867ad', 'reflection_question', $gs${"question":"What practical step can you take to show compassion and share the gospel with that person?"}$gs$::jsonb, 41, true, true)
