insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('f11244e1-a1cf-5b0b-963f-d69d7078d290', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', $gs$Have I understood repentance as merely feeling sorry, rather than this passage’s call to actual, comprehensive turning?$gs$, 4),
  ('4dbed67d-7b92-5940-9230-f84d29bc4ce4', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', $gs$What does genuine turning toward God, not just away from behavior, look like practically in my own life?$gs$, 5),
  ('3bd5b4f1-ef66-5362-9398-6a91b421d490', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', $gs$Have I ever repented in feeling but not in actual, ongoing direction and allegiance?$gs$, 6),
  ('e47dea1b-9f65-52e2-9160-48614d06b1e6', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', $gs$What specific area of my life still requires this kind of genuine, comprehensive turning?$gs$, 7),
  ('60aab094-28a1-5839-aa9f-1dc0ff340d38', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', $gs$How can I understand repentance as ongoing beginning, not a single, completed event requiring perfect follow-through?$gs$, 8)
on conflict (id) do nothing;
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('2840aaf7-af90-5065-a398-a69426a2a27b', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 'paragraph', $gs${"text":"About this part\n\nThis plan teaches believers to understand the genuine, biblical response the gospel requires — examining Scripture’s teaching regarding repentance, faith, and confession as the actual, necessary components of genuine conversion, and practical wisdom for making this response real throughout ongoing life and continued relationship with Christ."}$gs$::jsonb, 1, false, false),
  ('a1a02e9f-c3e9-50f8-858b-156a5e976f25', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 'paragraph', $gs${"text":"Root Scripture\n\n“The time is fulfilled, and the kingdom of God is at hand. Repent, and believe in the gospel.” — Mark 1:15"}$gs$::jsonb, 2, false, false),
  ('6dae7bb0-4e4d-5d30-b4cc-abcddebdb1ea', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 'paragraph', $gs${"text":"Lecture\n\nUnderstanding the gospel’s content is not the same as genuinely responding to it. Scripture consistently pairs two essential responses — repentance and faith — as the necessary, God-enabled human response to the good news of Christ’s death and resurrection. This response involves genuine turning from sin, genuine trust in Christ alone, and genuine, open confession of who He is. This is not a mechanical transaction completed by reciting particular words, but an actual, heartfelt turning of the whole person toward God. This plan explores what genuine repentance and saving faith actually involve, why confession and surrender matter, and practical wisdom for making this response real — through prayer, through telling someone, and through ongoing, lifelong response — throughout continued life and relationship with Christ."}$gs$::jsonb, 3, false, false),
  ('31f24c27-5e7c-5a0d-82cb-89ad9f1c421d', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 'paragraph', $gs${"text":"Study question 1\n\nWhy does Peter’s specific instruction — repentance leading to genuine conversion and blotted-out sin — reveal that repentance involves an actual, comprehensive turning, not merely feeling sorry while continuing in the same, unchanged direction?\n\nPeter’s specific instruction reveals repentance as actual, comprehensive turning, since leading to genuine conversion establishes this real change of direction, meaning repentance involves this actual turning, not merely feeling sorry while remaining unchanged, but this passage’s specific instruction particularly requiring recognition of genuine, comprehensive turning as characteristic of authentic, biblical repentance throughout believers’ actual, genuine response to the gospel’s call."}$gs$::jsonb, 6, false, false),
  ('b496a1b3-2888-5a7d-b11a-6c41a1fcbd9a', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 'paragraph', $gs${"text":"Study question 2\n\nHow does understanding repentance as turning toward God, not merely turning away from specific behaviors, clarify that this response is fundamentally relational, involving a change of allegiance and direction, not merely a behavioral checklist to complete?\n\nUnderstanding repentance as turning toward God clarifies its relational nature, since turning toward, not merely away from, establishes this relational reality, meaning repentance is fundamentally about changed allegiance and direction, not merely behavioral checklist completion, but this passage’s specific teaching requiring this relational understanding as characteristic of genuine, biblical repentance throughout believers’ comprehensive, actual response and continued relationship with God."}$gs$::jsonb, 7, false, false),
  ('5c3a762b-87d6-56d4-afa9-8d264742ad9f', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 'paragraph', $gs${"text":"Important Distinction\n\nGenuine repentance does not require having every specific sin already identified and addressed before responding to God; it means honestly beginning to turn in a new direction, trusting that ongoing, specific change follows this genuine turning, not precedes it."}$gs$::jsonb, 8, false, false),
  ('c645ef12-7059-5933-b697-a84c61c8e773', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 'paragraph', $gs${"text":"Lesson Assignment\n\n1. Read Acts 3:19-21 and reflect on repentance as genuine, comprehensive turning toward God.\n2. Identify a specific area of your life requiring this kind of genuine, ongoing turning.\n3. Take a concrete step of turning in this specific area this week.\n4. Discuss with your peer guide how they understand repentance as relational, not merely behavioral.\n5. Journal about your own, ongoing journey of genuine, continued repentance and turning toward God."}$gs$::jsonb, 10, false, false),
  ('8d0e6373-1f84-5761-9073-d787de05853c', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 'reflection_question', $gs${"question":"Have I understood repentance as merely feeling sorry, rather than this passage’s call to actual, comprehensive turning?"}$gs$::jsonb, 15, true, true),
  ('65dcced2-f973-5944-ada8-8e8cdf9baa31', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 'reflection_question', $gs${"question":"What does genuine turning toward God, not just away from behavior, look like practically in my own life?"}$gs$::jsonb, 16, true, true),
  ('db7c584a-79f8-5b54-b833-0d130cc6e71e', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 'reflection_question', $gs${"question":"Have I ever repented in feeling but not in actual, ongoing direction and allegiance?"}$gs$::jsonb, 17, true, true),
  ('04a861fb-b300-59f9-805a-07c61d3d67a7', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 'reflection_question', $gs${"question":"What specific area of my life still requires this kind of genuine, comprehensive turning?"}$gs$::jsonb, 18, true, true),
  ('b2c1407c-f6a7-55d6-b497-2df540f38b50', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 'reflection_question', $gs${"question":"How can I understand repentance as ongoing beginning, not a single, completed event requiring perfect follow-through?"}$gs$::jsonb, 19, true, true)
