  ('4cd5c064-3467-5e8e-aabf-9119436c35ee', '8b45b631-1b83-59a7-b274-6f1ab0857d7d', 'reflection_question', $gs${"question":"What would it look like to actively turn toward God while trusting Him to enable this very turning?"}$gs$::jsonb, 14, true, true),
  ('5a35de76-6039-5e05-9798-4dc27852081a', '8b45b631-1b83-59a7-b274-6f1ab0857d7d', 'reflection_question', $gs${"question":"How could I explain this comforting truth to someone who feels hopeless about ever genuinely changing?"}$gs$::jsonb, 15, true, true),
