  ('eb3f56bc-481a-58aa-ac0c-93c3986db762', '23de88d5-aa6f-5e7f-a5e6-b41ccdfcd6f2', 'reflection_question', $gs${"question":"How does this passage’s exclusive teaching provide freedom from any such subtle, added requirement?"}$gs$::jsonb, 13, true, true),
