  ('60ca8ab0-eb51-5f08-b653-0ffc08623f64', '23de88d5-aa6f-5e7f-a5e6-b41ccdfcd6f2', 'reflection_question', $gs${"question":"How would I explain “faith alone” clearly to someone confused about the relationship between faith and works?"}$gs$::jsonb, 15, true, true),
