insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('5e5258e2-41c7-501b-8d6b-4359bd7026aa', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', $gs$Have I based my confidence in salvation more on my feelings than on God’s own, actual, stated promise?$gs$, 4),
  ('31a1367b-cbbc-54fe-af7b-e9bd9dcc33bf', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', $gs$What specific promise from Scripture could I return to on a day I feel spiritually distant or uncertain?$gs$, 5),
  ('19730c61-ddd3-5719-9941-3e89451605b0', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', $gs$How does understanding assurance as promise-based, not feeling-based, change how I think about my own, occasional doubt?$gs$, 6),
  ('526cf682-743e-528a-9e0f-4477cfe0a2b2', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', $gs$What would it look like to actively remind myself of this promise the next time my feelings genuinely fluctuate?$gs$, 7),
  ('a93bbaa7-11f0-5986-b76b-872cc114711c', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', $gs$How can I help someone else struggling with doubt understand this same, stable, promise-based foundation?$gs$, 8)
on conflict (id) do nothing;
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('660891c5-f8df-5698-b42d-28348f065c56', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'paragraph', $gs${"text":"About this part\n\nThis plan teaches believers to understand genuine, biblical assurance of salvation — examining Scripture’s teaching regarding the basis of this assurance in God’s promise, the genuine evidences that accompany salvation, common obstacles that undermine confident assurance, and practical wisdom for living with settled confidence throughout ongoing spiritual life and faith."}$gs$::jsonb, 1, false, false),
  ('f2121e34-9032-5744-9ac8-d3892b96ecb4', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'paragraph', $gs${"text":"Root Scripture\n\n“These things I have written to you who believe in the name of the Son of God, that you may know that you have eternal life.” — 1 John 5:13"}$gs$::jsonb, 2, false, false),
  ('5358d537-84bb-5ed9-94f2-fe5c0ab59c30', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'paragraph', $gs${"text":"Lecture\n\nMany genuine believers spend years wrestling with doubt about whether their salvation is real, often because they have grounded their assurance in the wrong foundation — their own feelings, their own performance, or comparison to others — rather than in God’s own, stated promise. Scripture reveals that assurance is meant to be a settled, confident reality, not an anxious, perpetual question mark, while also honestly acknowledging genuine evidences that accompany true salvation and genuine obstacles that commonly undermine confidence. This plan explores the actual basis of genuine assurance, the evidences Scripture describes as accompanying salvation, common obstacles believers face, and practical wisdom for living in settled, confident assurance throughout ongoing spiritual life and continued relationship with God."}$gs$::jsonb, 3, false, false),
  ('2f5d15b1-de3b-5c42-bad5-7a61283253b5', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'paragraph', $gs${"text":"Study question 1\n\nWhy does John’s specific purpose — writing so believers may genuinely “know,” not merely hope — reveal that assurance is meant to rest on God’s own, written promise rather than the believer’s own, fluctuating emotional experience from day to day?\n\nJohn’s specific purpose reveals assurance’s foundation in God’s promise, since writing so believers may “know” establishes this certain, promise-based foundation, meaning genuine assurance should rest on this stated promise, not fluctuating emotional experience, but this passage’s specific purpose particularly requiring recognition of promise, not feeling, as the actual, stable basis for genuine assurance throughout believers’ ongoing confidence and understanding of their own, secure salvation."}$gs$::jsonb, 6, false, false),
  ('0e6a7805-d913-5669-9a32-708fc4b40738', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'paragraph', $gs${"text":"Study question 2\n\nHow does grounding assurance in promise rather than feeling provide stable confidence that remains genuinely unaffected by a believer’s changing, day-to-day emotional state, since promises, unlike feelings, do not fluctuate with circumstance or mood?\n\nGrounding assurance in promise provides stable confidence unaffected by changing emotion, since promises, unlike feelings, remain constant regardless of circumstance, meaning believers should ground their confidence in this stable, unfluctuating promise, not their own changing emotional state, but resting in this passage’s stated, unchanging promise throughout their ongoing confidence and continued, secure relationship with God regardless of daily, emotional fluctuation."}$gs$::jsonb, 7, false, false),
  ('51d3d64d-71c3-5ddc-bda8-63eeda95243a', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'paragraph', $gs${"text":"Important Distinction\n\nGrounding assurance in promise does not mean feelings are unimportant or should be suppressed; it means these feelings should not serve as the actual foundation for assurance, which instead rests on God’s own, unchanging, stated word."}$gs$::jsonb, 8, false, false),
  ('113b23d4-88aa-51c0-a8c2-dcea0a72a72a', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'paragraph', $gs${"text":"Lesson Assignment\n\n1. Read 1 John 5:11-13 and write out John’s stated promise in your own words.\n2. Write this promise somewhere you will see it regularly during moments of doubt or uncertainty.\n3. Identify a recent moment when your feelings, not this promise, shaped your sense of assurance.\n4. Discuss with your peer guide how they return to God’s promise during their own seasons of doubt.\n5. Journal about grounding your confidence in this stable, unchanging promise going forward."}$gs$::jsonb, 10, false, false),
  ('e0f5b4cd-2a22-558e-bba0-3b0c5e55b24e', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'reflection_question', $gs${"question":"Have I based my confidence in salvation more on my feelings than on God’s own, actual, stated promise?"}$gs$::jsonb, 15, true, true),
  ('e109746d-f786-50a6-96bd-ccbf4c4a0958', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'reflection_question', $gs${"question":"What specific promise from Scripture could I return to on a day I feel spiritually distant or uncertain?"}$gs$::jsonb, 16, true, true),
  ('d2de7c19-469c-56a7-be4a-4664e4245d58', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'reflection_question', $gs${"question":"How does understanding assurance as promise-based, not feeling-based, change how I think about my own, occasional doubt?"}$gs$::jsonb, 17, true, true),
  ('b289cca8-73dd-59bc-8f5b-6c6169b02b6d', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'reflection_question', $gs${"question":"What would it look like to actively remind myself of this promise the next time my feelings genuinely fluctuate?"}$gs$::jsonb, 18, true, true),
  ('44b629d8-1672-5268-be15-9ad75ff22272', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'reflection_question', $gs${"question":"How can I help someone else struggling with doubt understand this same, stable, promise-based foundation?"}$gs$::jsonb, 19, true, true)
