  ('af248c0e-8638-5d81-9d26-2330f31293d4', 'b02d9c47-fa95-536b-bc96-8918ca0c49b6', 'reflection_question', $gs${"question":"How does understanding Christ’s sacrifice as genuinely “once for all” provide stability amid my own, continued imperfection?"}$gs$::jsonb, 13, true, true),
  ('d75163a7-006b-5b71-ad06-95a4eeff48e1', 'b02d9c47-fa95-536b-bc96-8918ca0c49b6', 'reflection_question', $gs${"question":"What present struggle or failure have I mistakenly allowed to threaten my confidence in this finished work?"}$gs$::jsonb, 14, true, true),
  ('8fda0281-3653-5c86-9263-d61d0174ac33', 'b02d9c47-fa95-536b-bc96-8918ca0c49b6', 'reflection_question', $gs${"question":"How would I explain this stable foundation to someone who feels their salvation depends on their own performance?"}$gs$::jsonb, 15, true, true),
