insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('9122e1a0-7bf6-599f-8a1f-7b92f47f4768', '5503890b-a95f-5f48-8a54-f2eea4162590', $gs$Have I experienced this internal witness — a growing sense of God as genuine Father — in my own spiritual life?$gs$, 4),
  ('6667a551-6129-5bea-a7e8-0c64cc79da93', '5503890b-a95f-5f48-8a54-f2eea4162590', $gs$How does understanding this witness as confirming, not primary, evidence help me maintain proper, stable assurance?$gs$, 5),
  ('b125e075-8ae8-5677-aa4a-b82730323c43', '5503890b-a95f-5f48-8a54-f2eea4162590', $gs$What has this internal sense of relationship with God looked like, practically, in my own, recent experience?$gs$, 6),
  ('40aefede-dcb2-5bac-a3f5-6bd7bc86a171', '5503890b-a95f-5f48-8a54-f2eea4162590', $gs$How can I hold this internal witness alongside, not instead of, the objective promises this study has explored?$gs$, 7),
  ('7b4496d1-0e64-5586-98ea-12f1465579c4', '5503890b-a95f-5f48-8a54-f2eea4162590', $gs$What would I say to someone who has never experienced this witness, yet trusts Christ genuinely?$gs$, 8)
on conflict (id) do nothing;
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('f55be684-03a1-5384-ac75-8af7f37b7131', '5503890b-a95f-5f48-8a54-f2eea4162590', 'paragraph', $gs${"text":"Study question 1\n\nWhy does Paul’s specific description — the Spirit genuinely “bearing witness” alongside the believer’s own spirit — reveal that God provides an additional, internal confirmation of genuine salvation, complementing rather than replacing Scripture’s own, external promise?\n\nPaul’s specific description reveals an additional, internal confirmation, since the Spirit genuinely “bearing witness” alongside the believer’s own spirit establishes this complementary confirmation, meaning God provides this internal witness, complementing, not replacing, Scripture’s promise, but this passage’s specific description particularly requiring recognition of this additional, internal confirmation as genuine, though secondary, evidence throughout believers’ comprehensive understanding of assurance’s various, genuine dimensions."}$gs$::jsonb, 3, false, false),
  ('99e7dc51-f213-5812-9d96-e01c9ccec035', '5503890b-a95f-5f48-8a54-f2eea4162590', 'paragraph', $gs${"text":"Study question 2\n\nHow does this internal witness typically manifest — a genuine, growing sense of God as Father, a desire for relationship with Him — providing gentle, confirming evidence rather than the primary, foundational basis this module’s earlier lessons have already established?\n\nThis internal witness typically manifests as growing sense of God as Father, providing gentle, confirming evidence rather than primary basis, meaning believers should recognize this internal witness as genuine, though secondary confirmation, not the primary foundation, but complementing this module’s earlier, established foundation of God’s promise and Christ’s finished work throughout believers’ comprehensive, layered understanding of genuine, biblical assurance."}$gs$::jsonb, 4, false, false),
  ('b307167a-db1c-578c-9068-571e18dc7d2e', '5503890b-a95f-5f48-8a54-f2eea4162590', 'paragraph', $gs${"text":"Important Distinction\n\nAffirming the Spirit’s witness does not mean this internal sense should become the primary basis for assurance, which remains grounded first in God’s objective promise and Christ’s finished work; the Spirit’s witness serves as confirming, not foundational, evidence."}$gs$::jsonb, 5, false, false),
  ('42fc49c4-3448-5e39-b2bb-1fde987f2432', '5503890b-a95f-5f48-8a54-f2eea4162590', 'paragraph', $gs${"text":"Lesson Assignment\n\n1. Read Romans 8:14-16 and reflect on the Spirit’s internal, confirming witness alongside God’s promise.\n2. Reflect on your own, growing sense of relationship with God as genuine Father.\n3. Journal about specific moments when this internal witness has felt genuinely present in your life.\n4. Discuss with your peer guide how they understand this witness as confirming, not primary, evidence.\n5. Thank God for this additional, internal confirmation alongside His objective, stated promise."}$gs$::jsonb, 7, false, false),
  ('508960d7-d85b-52de-90df-59096b06f83c', '5503890b-a95f-5f48-8a54-f2eea4162590', 'reflection_question', $gs${"question":"Have I experienced this internal witness — a growing sense of God as genuine Father — in my own spiritual life?"}$gs$::jsonb, 12, true, true),
  ('f37ba172-3300-5562-b238-4a15af0127e8', '5503890b-a95f-5f48-8a54-f2eea4162590', 'reflection_question', $gs${"question":"How does understanding this witness as confirming, not primary, evidence help me maintain proper, stable assurance?"}$gs$::jsonb, 13, true, true),
  ('4e7fcdc0-29a0-5107-a8c0-1b0a0aa41906', '5503890b-a95f-5f48-8a54-f2eea4162590', 'reflection_question', $gs${"question":"What has this internal sense of relationship with God looked like, practically, in my own, recent experience?"}$gs$::jsonb, 14, true, true),
  ('08f1ab58-1e77-5551-901c-b2b5d9815393', '5503890b-a95f-5f48-8a54-f2eea4162590', 'reflection_question', $gs${"question":"How can I hold this internal witness alongside, not instead of, the objective promises this study has explored?"}$gs$::jsonb, 15, true, true),
  ('3d885123-58a9-5a3e-810f-b2eba07b7e46', '5503890b-a95f-5f48-8a54-f2eea4162590', 'reflection_question', $gs${"question":"What would I say to someone who has never experienced this witness, yet trusts Christ genuinely?"}$gs$::jsonb, 16, true, true)
