insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('c9d5e6b0-6bff-5384-9d61-dfb1da42209f', '708a0bde-50bd-5033-9c4e-81994f7d581b', 'paragraph', $gs${"text":"Study question 1\n\nWhy does Jesus’s specific correction — redirecting comparison toward personal focus — reveal genuine danger in comparing one’s own assurance or spiritual experience to someone else’s genuinely different journey and testimony?\n\nJesus’s specific correction reveals genuine danger in comparison, since redirecting Peter’s focus establishes this important, corrective principle, meaning believers must similarly resist comparing their own assurance to someone else’s different journey, instead maintaining Jesus’s redirected focus toward their own, personal relationship with Him, regardless of how this compares to others’ different, genuine testimonies and spiritual experiences throughout their own assurance and continued faith."}$gs$::jsonb, 3, false, false),
  ('455ff56a-5d8e-5bda-abe4-c5c7edcc7ef8', '708a0bde-50bd-5033-9c4e-81994f7d581b', 'paragraph', $gs${"text":"Study question 2\n\nHow does this comparison often develop through observing someone else’s more dramatic conversion story or more intense, emotional spiritual experience, requiring intentional redirection toward one’s own, genuine relationship with Christ rather than this destructive, comparative evaluation?\n\nThis comparison often develops through observing more dramatic conversion stories, requiring intentional redirection toward personal relationship, meaning believers should actively resist this comparative evaluation, following Jesus’s own redirection, not comparing their own, quieter journey to someone else’s more dramatic testimony, but pursuing this passage’s corrective focus on their own, genuine, personal relationship with Christ throughout their own, continued assurance and faith."}$gs$::jsonb, 4, false, false),
  ('0ad4e0e6-e3a4-5045-b07a-aa57ddc2046a', '708a0bde-50bd-5033-9c4e-81994f7d581b', 'paragraph', $gs${"text":"Important Distinction\n\nResisting comparison does not mean dismissing genuine encouragement from hearing others’ testimonies; it means this encouragement should never become the standard by which your own, genuine relationship with Christ is measured or doubted."}$gs$::jsonb, 5, false, false),
  ('8ccbae14-1898-5f48-a109-91fccf442eb8', '708a0bde-50bd-5033-9c4e-81994f7d581b', 'paragraph', $gs${"text":"Lesson Assignment\n\n1. Read John 21:20-22 and reflect on Jesus’s specific correction of comparative evaluation.\n2. Identify a specific comparison currently threatening your own confidence and assurance.\n3. Practice this redirection toward your own, personal relationship with Christ this week.\n4. Discuss with your peer guide how they have overcome comparison within their own journey of assurance.\n5. Journal about your own, unique relationship with Christ, not measured by someone else’s different journey."}$gs$::jsonb, 7, false, false),
  ('a15f0e27-1571-5e3e-83ed-361d0bb325cf', '708a0bde-50bd-5033-9c4e-81994f7d581b', 'reflection_question', $gs${"question":"Have I compared my own, quieter journey to someone else’s more dramatic conversion or spiritual experience?"}$gs$::jsonb, 12, true, true),
  ('5604b11b-3e38-5ee8-b78d-958ea8828fd7', '708a0bde-50bd-5033-9c4e-81994f7d581b', 'reflection_question', $gs${"question":"What specific comparison currently threatens my confidence regarding my own, genuine relationship with Christ?"}$gs$::jsonb, 13, true, true),
  ('dc121346-d522-5cc2-acd3-65e7b669abf3', '708a0bde-50bd-5033-9c4e-81994f7d581b', 'reflection_question', $gs${"question":"How does Jesus’s specific correction provide important perspective for redirecting my own focus and comparison?"}$gs$::jsonb, 14, true, true),
  ('a1e4f140-a2cb-5c49-b37f-3b134e13489d', '708a0bde-50bd-5033-9c4e-81994f7d581b', 'reflection_question', $gs${"question":"What would it look like to practice this redirection, following Jesus’s model, regarding a specific comparison?"}$gs$::jsonb, 15, true, true),
  ('76baba59-835c-5933-92dc-a8b0bb41c910', '708a0bde-50bd-5033-9c4e-81994f7d581b', 'reflection_question', $gs${"question":"How can I find genuine encouragement in others’ testimonies without using them as my own standard of measurement?"}$gs$::jsonb, 16, true, true)
