insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('53903c05-76d5-50d0-897d-d47de9786b45', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', $gs$Have I understood baptism as merely private, symbolic ritual, rather than this passage’s genuine, public declaration?$gs$, 4),
  ('5c026d55-0e53-5164-8a08-30a292d6452a', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', $gs$What courage does taking this visible, public step require in my own, specific circumstances and relationships?$gs$, 5),
  ('fd6a96fb-b4d5-5983-a31e-de5aee442865', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', $gs$If I have not yet been baptized, what has genuinely delayed this step, and how might I address that?$gs$, 6),
  ('a1a4c7df-3325-566b-bce0-64b882d7b3e8', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', $gs$If I have been baptized, what do I remember about the courage that public step required of me?$gs$, 7),
  ('5d0d8e1b-9bcb-5b57-9286-1451c7070862', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', $gs$Who would I want present to witness this significant, public declaration of my faith in Christ?$gs$, 8)
on conflict (id) do nothing;
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('1a980b29-c409-561b-8da3-eff797db8ec0', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', 'paragraph', $gs${"text":"About this part\n\nThis plan teaches believers to understand genuine, biblical baptism — examining Scripture’s teaching regarding its meaning as public declaration and identification with Christ’s death, burial, and resurrection, its pattern throughout the New Testament, and practical wisdom for approaching and living out this significant, obedient step throughout ongoing faith and discipleship."}$gs$::jsonb, 1, false, false),
  ('4c8e81ed-1eb7-564a-823c-a6a946a2aef6', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', 'paragraph', $gs${"text":"Root Scripture\n\n“Therefore we were buried with Him through baptism into death, that just as Christ was raised from the dead by the glory of the Father, even so we also should walk in newness of life.” — Romans 6:4"}$gs$::jsonb, 2, false, false),
  ('75dc7a9b-bccf-5071-865e-9105aa10ea3b', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', 'paragraph', $gs${"text":"Lecture\n\nBaptism represents one of the most visible, significant steps of obedience a new believer takes — a public, physical declaration of an inward, spiritual reality that has already occurred. Scripture consistently connects baptism to genuine faith already present, following conversion as its expected, early expression rather than functioning as the means by which salvation itself is secured. Baptism pictures something profound: identification with Christ’s own death, burial, and resurrection, portraying the old life genuinely put to death and new life genuinely raised. This plan explores baptism’s genuine, biblical meaning, its consistent pattern throughout Scripture, practical wisdom for preparing to take this step, and how believers can live out the ongoing identity this baptism pictures throughout their continued, growing faith and discipleship."}$gs$::jsonb, 3, false, false),
  ('3e375753-fcab-56d0-bfc9-b2c754add7cd', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', 'paragraph', $gs${"text":"Study question 1\n\nWhy does this passage’s specific sequence — genuinely receiving the word, then being baptized — reveal that baptism represents a public, outward declaration following genuine, prior faith, not remaining confined to merely private, internal belief alone?\n\nThis passage’s specific sequence reveals baptism as public declaration following prior faith, since receiving the word then being baptized establishes this sequence, meaning baptism represents this public, outward declaration, not remaining confined to private belief, but this passage’s specific sequence particularly requiring recognition of baptism’s genuine, public function as characteristic of the early church’s consistent pattern and practice throughout Scripture’s testimony regarding genuine, biblical baptism."}$gs$::jsonb, 6, false, false),
  ('926b1849-b5e3-5975-afbf-38c01118fbc4', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', 'paragraph', $gs${"text":"Study question 2\n\nHow does this public declaration require genuine courage, openly identifying with Christ before others through this visible, physical act, rather than maintaining private, unexpressed faith that avoids the genuine, social visibility baptism specifically requires?\n\nThis public declaration requires genuine courage, since visible, physical identification differs from private, unexpressed faith, meaning baptism requires this courageous, public step, not remaining private, but pursuing this passage’s called-for, visible declaration despite whatever genuine, social visibility this act specifically requires throughout believers’ public witness and identification with Christ before others."}$gs$::jsonb, 7, false, false),
  ('092293bb-20f9-5dd0-b71f-9fa8693f6263', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', 'paragraph', $gs${"text":"Important Distinction\n\nUnderstanding baptism as public declaration does not mean private, personal faith is somehow incomplete without immediate baptism; it means genuine faith, once present, should not indefinitely delay this passage’s calledfor, appropriate, public expression and declaration."}$gs$::jsonb, 8, false, false),
  ('89cf3dd0-a52b-5bf2-bd66-a547a1a9cdcd', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', 'paragraph', $gs${"text":"Lesson Assignment\n\n1. Read Acts 2:38-41 and reflect on baptism as public declaration following genuine, prior faith.\n2. If you have not yet been baptized, discuss this step with your pastor or mentor this week.\n3. If you have been baptized, write about what that public, courageous step meant to you.\n4. Discuss with your peer guide how they prepared for and experienced their own baptism.\n5. Journal about your own readiness or growth regarding this significant, public declaration of faith."}$gs$::jsonb, 10, false, false),
  ('456f37ca-1993-5655-9234-c98999e2315d', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', 'reflection_question', $gs${"question":"Have I understood baptism as merely private, symbolic ritual, rather than this passage’s genuine, public declaration?"}$gs$::jsonb, 15, true, true),
  ('f53d5fd8-894a-5b58-9fa9-a5d81f50bc7b', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', 'reflection_question', $gs${"question":"What courage does taking this visible, public step require in my own, specific circumstances and relationships?"}$gs$::jsonb, 16, true, true),
  ('411ceab7-4e77-5c6c-86f0-7a9c8910b3cb', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', 'reflection_question', $gs${"question":"If I have not yet been baptized, what has genuinely delayed this step, and how might I address that?"}$gs$::jsonb, 17, true, true),
  ('663b7d90-af61-5a1a-8728-280be5e9d2b4', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', 'reflection_question', $gs${"question":"If I have been baptized, what do I remember about the courage that public step required of me?"}$gs$::jsonb, 18, true, true),
  ('6aba6d3a-7804-5139-ad3f-ca5f9893b722', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', 'reflection_question', $gs${"question":"Who would I want present to witness this significant, public declaration of my faith in Christ?"}$gs$::jsonb, 19, true, true)
