insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('69717b72-5dd4-5388-91e2-a4618d92a07a', '2347ca3a-44af-59d2-9c7b-758e91c11b85', $gs$What specific fear or hesitation, if any, have I experienced regarding pursuing baptism myself?$gs$, 4),
  ('8394d197-41ec-5016-9d89-cd67019ff7d0', '2347ca3a-44af-59d2-9c7b-758e91c11b85', $gs$How does this passage’s promise provide comfort and courage for addressing this genuine hesitation?$gs$, 5),
  ('9b48c211-91de-598a-a93f-4426768e9a42', '2347ca3a-44af-59d2-9c7b-758e91c11b85', $gs$Are there genuine, practical concerns I need to wisely navigate, distinct from mere emotional discomfort alone?$gs$, 6),
  ('9db01e61-7acc-549e-8a47-646a4c4b848c', '2347ca3a-44af-59d2-9c7b-758e91c11b85', $gs$What would it look like to take one, courageous step toward baptism despite this hesitation this week?$gs$, 7),
  ('d83edace-cfbf-5196-8080-a13188771f96', '2347ca3a-44af-59d2-9c7b-758e91c11b85', $gs$Who could I talk to honestly about this fear, receiving encouragement and support as I consider this step?$gs$, 8)
on conflict (id) do nothing;
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('2dacf22b-b46f-5c16-825c-1c11c4d0889e', '2347ca3a-44af-59d2-9c7b-758e91c11b85', 'paragraph', $gs${"text":"Study question 1\n\nWhy might believers experience genuine fear or hesitation regarding baptism — public visibility, family reaction, personal nervousness — requiring this passage’s specific promise of God’s given power, love, and sound mind to overcome this common, understandable hesitation?\n\nBelievers may experience genuine fear or hesitation, requiring this passage’s specific promise as necessary counter, since public visibility and family reaction commonly produce genuine, understandable hesitation, meaning believers experiencing this fear should recognize God’s genuine provision countering it, actively trusting this promised power rather than allowing hesitation to indefinitely delay this important, obedient step throughout their own, genuine preparation for baptism."}$gs$::jsonb, 3, false, false),
  ('010b0570-5841-5455-a1ac-f2321e49e7e2', '2347ca3a-44af-59d2-9c7b-758e91c11b85', 'paragraph', $gs${"text":"Study question 2\n\nHow does remembering that this fear, however genuine, does not change baptism’s genuine importance or Christ’s own clear command provide motivation for pursuing this step despite hesitation, trusting God’s provided strength rather than requiring complete comfort first?\n\nRemembering that fear does not change baptism’s importance provides motivation despite hesitation, since Christ’s clear command remains regardless of comfort level, meaning believers should pursue this step despite genuine hesitation, not requiring complete comfort first, but trusting this passage’s promised strength throughout their own, courageous pursuit of baptism despite whatever genuine fear or nervousness they might currently experience and feel."}$gs$::jsonb, 4, false, false),
  ('4e55f3d5-88f5-5d88-987c-ba1e28703503', '2347ca3a-44af-59d2-9c7b-758e91c11b85', 'paragraph', $gs${"text":"Important Distinction\n\nOvercoming fear regarding baptism does not mean dismissing genuine, practical concerns — family relationships, safety, timing — that may require wise, thoughtful navigation; it means not allowing mere emotional discomfort alone to indefinitely prevent this important, obedient step."}$gs$::jsonb, 5, false, false),
  ('8e332d18-0da2-5109-a0a2-4e0816bd7d55', '2347ca3a-44af-59d2-9c7b-758e91c11b85', 'paragraph', $gs${"text":"Lesson Assignment\n\n1. Read 2 Timothy 1:6-8 and reflect on God’s given power, love, and sound mind countering fear.\n2. Identify your own, specific fear or hesitation regarding baptism, if applicable to your situation.\n3. Talk with your mentor or pastor honestly about this fear, seeking encouragement and practical wisdom.\n4. Discuss with your peer guide how they overcame their own hesitation in pursuing baptism.\n5. Journal about your own, growing courage as you consider or prepare for this significant step."}$gs$::jsonb, 7, false, false),
  ('5e5bbcc8-b3ba-571d-9864-18e9b40b56b2', '2347ca3a-44af-59d2-9c7b-758e91c11b85', 'reflection_question', $gs${"question":"What specific fear or hesitation, if any, have I experienced regarding pursuing baptism myself?"}$gs$::jsonb, 12, true, true),
  ('91064a41-6adf-5b5f-b72e-384e030cff07', '2347ca3a-44af-59d2-9c7b-758e91c11b85', 'reflection_question', $gs${"question":"How does this passage’s promise provide comfort and courage for addressing this genuine hesitation?"}$gs$::jsonb, 13, true, true),
  ('7149fad7-5d86-5fcf-be78-b9ec04510f26', '2347ca3a-44af-59d2-9c7b-758e91c11b85', 'reflection_question', $gs${"question":"Are there genuine, practical concerns I need to wisely navigate, distinct from mere emotional discomfort alone?"}$gs$::jsonb, 14, true, true),
  ('124abc35-9dcf-5c22-a1a7-08c4d84667e9', '2347ca3a-44af-59d2-9c7b-758e91c11b85', 'reflection_question', $gs${"question":"What would it look like to take one, courageous step toward baptism despite this hesitation this week?"}$gs$::jsonb, 15, true, true),
  ('76ba33e5-f0ec-58d8-b9d7-bf4eb17c12e9', '2347ca3a-44af-59d2-9c7b-758e91c11b85', 'reflection_question', $gs${"question":"Who could I talk to honestly about this fear, receiving encouragement and support as I consider this step?"}$gs$::jsonb, 16, true, true)
on conflict (id) do nothing;
