insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('5f434445-d97d-53f7-8d5c-32cfc4456984', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', $gs$Have I treated my own baptism as merely completed, past ceremony, without this passage’s call to ongoing, present walking?$gs$, 4),
  ('ce4e58e8-fa34-5418-bea2-ea0d01b877bc', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', $gs$What specific area of my life requires greater, practical alignment with this pictured, new-life reality?$gs$, 5),
  ('75c26533-afd2-5468-a04b-7f2bbf6012c3', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', $gs$How does remembering my baptism motivate greater faithfulness in this specific, ongoing area?$gs$, 6),
  ('c5fb5627-76ac-5869-8ef3-3192e980c063', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', $gs$What would it look like to more intentionally “walk in newness of life” within a specific choice this week?$gs$, 7),
  ('b89c239a-81cc-51ce-92f9-3684de7b8c51', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', $gs$How can I hold genuine grace for incomplete transformation while still pursuing this ongoing, faithful direction?$gs$, 8)
on conflict (id) do nothing;
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('c2df9662-f091-5fe3-9398-22043ee50942', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', 'paragraph', $gs${"text":"Study question 1\n\nWhy does Paul’s specific instruction — genuinely “walking” in newness, not merely having been baptized once — reveal that baptism’s picture requires ongoing, practical outworking throughout believers’ continued, daily life, not remaining confined to a single, completed event?\n\nPaul’s specific instruction reveals baptism requiring ongoing outworking, since genuinely “walking” in newness, not merely having been baptized once, establishes this continued, practical requirement, meaning baptism’s picture requires this ongoing outworking throughout daily life, not remaining confined to a single event, but this passage’s specific instruction particularly requiring recognition of this continued, practical walking as characteristic of genuine, ongoing response to baptism’s pictured reality throughout believers’ entire, continuing life and faith."}$gs$::jsonb, 3, false, false),
  ('7e482dde-ca0a-52ab-b003-f8ce6c5c2a70', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', 'paragraph', $gs${"text":"Study question 2\n\nHow does this ongoing walk require believers to actively, practically live out the death-to-old-life and resurrection-tonew-life pattern baptism pictures, in specific, daily choices rather than treating baptism as merely completed, past ceremony disconnected from present, continued practice?\n\nThis ongoing walk requires actively living out this pattern in daily choices, since present, continued practice differs from merely completed, past ceremony, meaning believers should actively practice this ongoing pattern in specific, daily choices, not treating baptism as merely past ceremony, but pursuing this passage’s called-for, continued walking throughout their present, ongoing life and daily, practical expression of the reality baptism specifically pictures and represents."}$gs$::jsonb, 4, false, false),
  ('2b88e2d7-5ef0-5be6-98e4-36bf439af209', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', 'paragraph', $gs${"text":"Important Distinction\n\nWalking in newness of life does not mean achieving flawless, complete transformation immediately; it means an ongoing, genuine direction toward this new life, even amid continued struggle, growth, and dependence on grace throughout this lifelong journey."}$gs$::jsonb, 5, false, false),
  ('3acef8b4-83fe-5364-9867-47224d9e6c60', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', 'paragraph', $gs${"text":"Lesson Assignment\n\n1. Read Romans 6:1-11 and reflect on walking in newness of life as ongoing response to baptism’s picture.\n2. Identify a specific area of your life requiring greater alignment with this new-life reality.\n3. Take a concrete step in this specific area this week, remembering your baptism’s meaning.\n4. Discuss with your peer guide how they continue walking in newness of life following their own baptism.\n5. Journal about your own, ongoing commitment to this continued walk throughout your life."}$gs$::jsonb, 7, false, false),
  ('6b32b387-d593-58c5-a2b6-4c50af54b606', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', 'reflection_question', $gs${"question":"Have I treated my own baptism as merely completed, past ceremony, without this passage’s call to ongoing, present walking?"}$gs$::jsonb, 12, true, true),
  ('52234a35-27cc-545c-9931-af8d2bc8eaf1', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', 'reflection_question', $gs${"question":"What specific area of my life requires greater, practical alignment with this pictured, new-life reality?"}$gs$::jsonb, 13, true, true),
  ('599dc948-8a3a-5fd0-a9b9-98bb8b3c01f3', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', 'reflection_question', $gs${"question":"How does remembering my baptism motivate greater faithfulness in this specific, ongoing area?"}$gs$::jsonb, 14, true, true),
  ('30fc1fa9-28e1-5290-91ee-68126a20d2fa', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', 'reflection_question', $gs${"question":"What would it look like to more intentionally “walk in newness of life” within a specific choice this week?"}$gs$::jsonb, 15, true, true),
  ('4925420c-19fd-52b4-b3ba-3b1471fe78eb', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', 'reflection_question', $gs${"question":"How can I hold genuine grace for incomplete transformation while still pursuing this ongoing, faithful direction?"}$gs$::jsonb, 16, true, true)
