insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('4d35230e-ac89-5383-ac76-dd84a2e850f8', '0adf8fc9-0c82-54f4-8247-af1beb5a0ebb', $gs$Have I assumed genuine discipleship applies primarily to pastors or especially devoted people, rather than to me personally?$gs$, 4),
  ('cee5e151-6010-52ef-9bd7-46fbfbaff7ba', '0adf8fc9-0c82-54f4-8247-af1beb5a0ebb', $gs$What would it look like to embrace this universal call as genuinely, personally applying to my own life?$gs$, 5),
  ('d31048d3-186d-5ae8-b011-41bc437c5a02', '0adf8fc9-0c82-54f4-8247-af1beb5a0ebb', $gs$How does this passage’s comprehensive commission challenge any passivity I have exhibited regarding my own growth?$gs$, 6),
  ('ba9e7cfe-190b-5300-a6ac-de3f00095697', '0adf8fc9-0c82-54f4-8247-af1beb5a0ebb', $gs$What specific area of discipleship do I sense God calling me to grow in, personally, right now?$gs$, 7),
  ('8bbe3959-6dfa-523f-9390-f371cd485135', '0adf8fc9-0c82-54f4-8247-af1beb5a0ebb', $gs$How can I encourage someone else to embrace this same, universal call within their own, particular life?$gs$, 8)
on conflict (id) do nothing;
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('10695cf3-ed33-58d9-8357-ecc78526de35', '0adf8fc9-0c82-54f4-8247-af1beb5a0ebb', 'paragraph', $gs${"text":"Study question 1\n\nWhy does Jesus’s specific, comprehensive commission — making disciples of “all” nations — reveal that discipleship represents universal calling for every believer, not remaining confined to merely especially devoted or particularly gifted individuals?\n\nJesus’s specific, comprehensive commission reveals discipleship as universal calling, since making disciples of “all” nations establishes this comprehensive, universal scope, meaning discipleship represents this universal calling for every believer, not remaining confined to especially devoted individuals alone, but this passage’s specific, comprehensive commission particularly requiring recognition of this universal expectation as characteristic of genuine, biblical Christianity throughout every believer’s own, personal life and continued growth."}$gs$::jsonb, 3, false, false),
  ('3a1ae8a3-e218-575c-be05-abdbf9bc5cfc', '0adf8fc9-0c82-54f4-8247-af1beb5a0ebb', 'paragraph', $gs${"text":"Study question 2\n\nHow does this universal expectation challenge believers who might assume genuine discipleship applies primarily to pastors, missionaries, or especially “spiritual” people, requiring correction toward this passage’s comprehensive, universal call and command?\n\nThis universal expectation directly challenges assuming special applicability, revealing instead this passage’s comprehensive, universal call, meaning believers should recognize discipleship as genuinely applying to them personally, not assuming this applies primarily to especially “spiritual” people, but embracing this passage’s comprehensive, universal command throughout their own, personal, ongoing pursuit of genuine, biblical discipleship and continued growth."}$gs$::jsonb, 4, false, false),
  ('18c8d8c6-fc23-5115-ae30-7d080b693976', '0adf8fc9-0c82-54f4-8247-af1beb5a0ebb', 'paragraph', $gs${"text":"Important Distinction\n\nEmphasizing discipleship’s universal scope does not mean every believer’s specific expression of discipleship looks identical; it means every believer genuinely shares this same, universal calling, however this specifically manifests within their own, particular life and circumstances."}$gs$::jsonb, 5, false, false),
  ('92b6ad6f-a01d-5c92-af0c-d83f6140c578', '0adf8fc9-0c82-54f4-8247-af1beb5a0ebb', 'paragraph', $gs${"text":"Lesson Assignment\n\n1. Read Matthew 28:18-20 and reflect on discipleship’s comprehensive, universal scope and application.\n2. Identify a specific way you have assumed discipleship applies to others more than to yourself.\n3. Correct this assumption, embracing this universal call personally, within a specific area this week.\n4. Discuss with your peer guide how they have grown in personally embracing this universal calling.\n5. Journal about your own, personal commitment to this universal call throughout your continued growth."}$gs$::jsonb, 7, false, false),
  ('a2c199e7-5f6a-5842-a185-171eb7c16038', '0adf8fc9-0c82-54f4-8247-af1beb5a0ebb', 'reflection_question', $gs${"question":"Have I assumed genuine discipleship applies primarily to pastors or especially devoted people, rather than to me personally?"}$gs$::jsonb, 12, true, true),
  ('ae7b093f-0768-5221-8964-d547a0c720db', '0adf8fc9-0c82-54f4-8247-af1beb5a0ebb', 'reflection_question', $gs${"question":"What would it look like to embrace this universal call as genuinely, personally applying to my own life?"}$gs$::jsonb, 13, true, true),
  ('c261ffed-ca97-53f4-98f2-923b81096165', '0adf8fc9-0c82-54f4-8247-af1beb5a0ebb', 'reflection_question', $gs${"question":"How does this passage’s comprehensive commission challenge any passivity I have exhibited regarding my own growth?"}$gs$::jsonb, 14, true, true),
  ('c5941e6e-31c6-5a78-9180-e837747b9170', '0adf8fc9-0c82-54f4-8247-af1beb5a0ebb', 'reflection_question', $gs${"question":"What specific area of discipleship do I sense God calling me to grow in, personally, right now?"}$gs$::jsonb, 15, true, true),
  ('efd3af8e-6b51-540a-9d22-d835023fcd65', '0adf8fc9-0c82-54f4-8247-af1beb5a0ebb', 'reflection_question', $gs${"question":"How can I encourage someone else to embrace this same, universal call within their own, particular life?"}$gs$::jsonb, 16, true, true)
