  ('7f422e76-31e7-5403-8a04-5f3a5ef92b23', '37000578-2b79-5f07-a301-44dfc2e8683f', 'reflection_question', $gs${"question":"What sustainable, realistic practice could I establish for regularly engaging Scripture, even if brief?"}$gs$::jsonb, 13, true, true),
  ('1acc5408-cc4f-5b72-a198-8b7851f2f989', '37000578-2b79-5f07-a301-44dfc2e8683f', 'reflection_question', $gs${"question":"How has my own growth been affected by seasons of consistent versus inconsistent engagement with the word?"}$gs$::jsonb, 14, true, true),
  ('3128db8f-1fe9-5a20-b681-643cc343708c', '37000578-2b79-5f07-a301-44dfc2e8683f', 'reflection_question', $gs${"question":"What would it look like to establish or strengthen this daily practice within my current schedule this week?"}$gs$::jsonb, 15, true, true),
