  ('af8edbf0-9783-5905-9e11-6a3a7d2d345a', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 'paragraph', $gs${"text":"Study question 1\n\nWhy does this passage’s simple, comprehensive instruction — praying “without ceasing” — reveal that prayer represents essential, ongoing communication with God a disciple’s continued growth actually, practically requires throughout their entire, daily life?\n\nThis passage’s simple, comprehensive instruction reveals prayer as essential, ongoing communication, since praying “without ceasing” establishes this continuous, ongoing practice, meaning prayer represents this essential communication a disciple’s growth requires, not optional or occasional practice, but this passage’s simple instruction particularly requiring recognition of this ongoing, essential prayer as characteristic of genuine, sustained discipleship throughout believers’ entire, continuing daily life and relationship with God."}$gs$::jsonb, 3, false, false),
  ('c127a6b1-7fb5-58d4-8d38-3aeb88dbdf4e', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 'paragraph', $gs${"text":"Study question 2\n\nHow does this consistent prayer life require both structured, dedicated time and ongoing, woven-throughout-the-day conversation, combining both dimensions rather than relying exclusively on either formal discipline or spontaneous, occasional prayer alone?\n\nThis consistent prayer life requires both structured time and ongoing conversation, since combining both dimensions differs from relying on either alone, meaning disciples should cultivate both structured, dedicated prayer and ongoing, woven-throughout conversation, not relying exclusively on either, but developing this passage’s called-for, comprehensive prayer practice throughout their ongoing, daily life and continued relationship with God and growth as maturing disciples."}$gs$::jsonb, 4, false, false),
  ('38b1ff09-9127-5968-829b-51901a4773b7', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 'paragraph', $gs${"text":"Important Distinction\n\nPraying without ceasing does not mean literally, constantly speaking words to God without pause; it means cultivating an ongoing, aware posture of communication and dependence throughout the day, alongside dedicated, focused times of structured prayer."}$gs$::jsonb, 5, false, false),
  ('3fd66cef-d8c3-521f-942c-79a7c177e336', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 'paragraph', $gs${"text":"Lesson Assignment\n\n1. Read 1 Thessalonians 5:16-18 and reflect on prayer as essential, ongoing communication with God.\n2. Establish or strengthen a specific, structured time of prayer within your current schedule this week.\n3. Practice cultivating ongoing, woven-throughout-the-day prayer alongside this structured time.\n4. Discuss with your peer guide how they have developed a consistent, sustained prayer life over time.\n5. Journal about your own, growing consistency and dependence on God through this essential practice."}$gs$::jsonb, 7, false, false),
  ('9d97137d-e45b-5462-ab84-9289c40c5a0a', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 'reflection_question', $gs${"question":"Have I neglected consistent prayer, or maintained only sporadic, occasional communication with God?"}$gs$::jsonb, 12, true, true),
  ('717e93d0-8870-5c86-9914-36f6550b4bfd', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 'reflection_question', $gs${"question":"What would it look like to develop both structured prayer time and ongoing, woven-throughout conversation?"}$gs$::jsonb, 13, true, true),
  ('948d58d7-bcc5-5cf3-972a-f8cf842a3003', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 'reflection_question', $gs${"question":"How has my own growth been shaped by seasons of consistent versus inconsistent prayer over time?"}$gs$::jsonb, 14, true, true),
  ('060f328f-139d-5519-bbb2-08daa20b4cd0', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 'reflection_question', $gs${"question":"What specific step could I take to establish or strengthen this practice within my current life this week?"}$gs$::jsonb, 15, true, true),
  ('90d45c80-d45e-5920-8ecb-a23cd0386fd9', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 'reflection_question', $gs${"question":"How can I cultivate genuine, ongoing awareness of God’s presence throughout my ordinary, daily activities?"}$gs$::jsonb, 16, true, true)
