  ('09778ada-9011-5b58-a62f-4845b060d46a', 'bf8d8cdd-9c1a-52fd-8aa4-9c996529155e', 'reflection_question', $gs${"question":"What specific qualities would I want in a mentor, and where might I find someone with these qualities?"}$gs$::jsonb, 14, true, true),
