  ('b93667fa-78d3-566b-bbb9-b8379bfb7b2e', 'f810a9b6-eb5a-50d7-aba9-f4481ffd4fa6', 'reflection_question', $gs${"question":"Who in my life might benefit from this kind of intentional investment, even at my own, current stage of growth?"}$gs$::jsonb, 13, true, true),
  ('d236a27c-3c7b-5cc8-ad3c-c39ba7cb90bc', 'f810a9b6-eb5a-50d7-aba9-f4481ffd4fa6', 'reflection_question', $gs${"question":"What specific insight or experience from my own journey could I share to help someone else grow?"}$gs$::jsonb, 14, true, true),
  ('e69caabf-b69e-5aac-8ca6-31f2689c0448', 'f810a9b6-eb5a-50d7-aba9-f4481ffd4fa6', 'reflection_question', $gs${"question":"How does this passage’s multi-generational vision challenge any passivity I have felt about investing in others?"}$gs$::jsonb, 15, true, true),
