insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('039f658d-8bf5-5698-abbd-ab8c3ec5f2b6', '969b543e-7afe-5b55-ac56-3c30c1addcd0', $gs$Have I pursued isolated, dramatic spiritual moments rather than this passage’s call to sustained, remaining fruit?$gs$, 4),
  ('88d08dfa-febc-5321-a308-8e801f7ebd3f', '969b543e-7afe-5b55-ac56-3c30c1addcd0', $gs$What lasting fruit has genuinely developed in my own life through the sustained practices this plan has explored?$gs$, 5),
  ('43a6b8af-268f-53f4-bbc4-9d4dabbcfc37', '969b543e-7afe-5b55-ac56-3c30c1addcd0', $gs$What lasting impact do I hope my own, continued discipleship will produce within others’ lives over time?$gs$, 6),
  ('a1365ecc-29f9-5d5c-98bb-4618446af4d7', '969b543e-7afe-5b55-ac56-3c30c1addcd0', $gs$How does understanding fruit as flowing from sustained practice motivate my own, continued faithfulness?$gs$, 7),
  ('866b22bc-9056-505f-b8a0-14660fe92bfc', '969b543e-7afe-5b55-ac56-3c30c1addcd0', $gs$What would it look like to more intentionally pursue this sustained, remaining fruit throughout my ongoing life?$gs$, 8)
on conflict (id) do nothing;
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('55122b33-57d1-5af3-b784-3d1d7a1c832f', '969b543e-7afe-5b55-ac56-3c30c1addcd0', 'paragraph', $gs${"text":"Study question 1\n\nWhy does Jesus’s specific instruction — bearing fruit that genuinely “remains” — reveal that genuine discipleship produces lasting, sustained impact, not remaining confined to merely temporary, fleeting religious activity or experience?\n\nJesus’s specific instruction reveals discipleship producing lasting impact, since fruit genuinely “remaining” establishes this sustained, not temporary, reality, meaning genuine discipleship produces this lasting, sustained impact, not merely temporary activity, but this passage’s specific instruction particularly requiring recognition of remaining fruit as characteristic of genuine, biblical discipleship throughout believers’ ongoing, sustained life and continued, lasting impact within others’ lives and God’s kingdom purpose."}$gs$::jsonb, 3, false, false),
  ('97a0cc7d-8054-5621-9783-76ebbe981cb3', '969b543e-7afe-5b55-ac56-3c30c1addcd0', 'paragraph', $gs${"text":"Study question 2\n\nHow does this remaining fruit typically develop through the sustained, ongoing practices this entire plan has explored — Scripture, prayer, church, mentoring relationship — rather than isolated, dramatic moments disconnected from this consistent, faithful pattern of ongoing discipleship and growth?\n\nThis remaining fruit typically develops through sustained, ongoing practices, since consistent pattern differs from isolated, dramatic moments, meaning believers should recognize remaining fruit as flowing from this consistent, sustained pattern this entire plan has explored, not isolated moments alone, but developing this passage’s called-for, remaining fruit throughout their consistent, faithful practice of genuine, ongoing discipleship and continued spiritual growth and development."}$gs$::jsonb, 4, false, false),
  ('5315c3ba-1fdd-56f9-8587-a1ba7087bae7', '969b543e-7afe-5b55-ac56-3c30c1addcd0', 'paragraph', $gs${"text":"Important Distinction\n\nBearing fruit that remains does not mean every believer’s specific impact looks identical or equally visible; it means genuine, faithful discipleship, sustained over time, produces lasting impact appropriate to each believer’s own, particular life and circumstances."}$gs$::jsonb, 5, false, false),
  ('429a6a2b-5544-5b3c-ac3f-b68e2b5ab05d', '969b543e-7afe-5b55-ac56-3c30c1addcd0', 'paragraph', $gs${"text":"Lesson Assignment\n\n1. Read John 15:1-8, 16 and reflect on genuine discipleship producing lasting, remaining fruit.\n2. Identify lasting fruit that has developed in your own life through sustained, faithful practice.\n3. Reflect on what lasting impact you hope your continued discipleship will produce in others’ lives.\n4. Discuss with your peer guide how sustained practice has produced lasting fruit in their own life.\n5. Journal about your own, continued commitment to this sustained, faithful pattern of genuine discipleship."}$gs$::jsonb, 7, false, false),
  ('d32b04c7-d156-5f59-a6e4-7ac2c0ed979b', '969b543e-7afe-5b55-ac56-3c30c1addcd0', 'reflection_question', $gs${"question":"Have I pursued isolated, dramatic spiritual moments rather than this passage’s call to sustained, remaining fruit?"}$gs$::jsonb, 12, true, true),
  ('68aab0ea-81c3-59f1-9f50-f61b706a9741', '969b543e-7afe-5b55-ac56-3c30c1addcd0', 'reflection_question', $gs${"question":"What lasting fruit has genuinely developed in my own life through the sustained practices this plan has explored?"}$gs$::jsonb, 13, true, true),
  ('9a851ea5-a469-50b4-a73e-6be0acc4cda8', '969b543e-7afe-5b55-ac56-3c30c1addcd0', 'reflection_question', $gs${"question":"What lasting impact do I hope my own, continued discipleship will produce within others’ lives over time?"}$gs$::jsonb, 14, true, true),
  ('983c79e0-5564-5366-8b31-af9191d730ff', '969b543e-7afe-5b55-ac56-3c30c1addcd0', 'reflection_question', $gs${"question":"How does understanding fruit as flowing from sustained practice motivate my own, continued faithfulness?"}$gs$::jsonb, 15, true, true),
  ('d972e589-057f-5fe7-ba17-57f133883467', '969b543e-7afe-5b55-ac56-3c30c1addcd0', 'reflection_question', $gs${"question":"What would it look like to more intentionally pursue this sustained, remaining fruit throughout my ongoing life?"}$gs$::jsonb, 16, true, true)
