insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('609880b1-069e-5900-b2a4-f637cd5a9a52', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', $gs$How has my understanding of the journey from convert to disciple — its call, essential habits, relational growth — changed through this study?$gs$, 4),
  ('270e0d4b-17ff-5583-9ec2-d71faba721f1', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', $gs$What has been the most significant truth I have learned about this ongoing, lifelong journey of following Jesus?$gs$, 5),
  ('558a4d42-053a-5bc4-9381-8169a271b95d', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', $gs$What specific practice from this plan do I want to carry forward as a lifelong habit of continued discipleship?$gs$, 6),
  ('4d13e313-cbaf-57cf-8e9d-02ee78ec0e61', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', $gs$What would it look like to still be faithfully following Jesus decades from now, in every season of my life?$gs$, 7),
  ('77fe6d06-d9b8-5ef6-b33e-6e8c113f618d', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', $gs$How has this study shaped your overall commitment to this ongoing journey throughout your continuing life and faith?$gs$, 8)
on conflict (id) do nothing;
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('fff3962f-3d29-5f39-b463-03f940398eac', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 'paragraph', $gs${"text":"Study question 1\n\nWhat is the ultimate posture believers are meant to carry throughout their entire lives regarding this significant, ongoing journey from convert to disciple?\n\nA sustained, lifelong commitment to ongoing learning and following, embracing discipleship’s genuine cost and universal call, cultivating the essential habits of Scripture, prayer, and church, growing through both mentoring and mutual, peer relationship, and continuing to bear lasting fruit despite genuine setback throughout every season of this entire, ongoing lifetime of following Jesus."}$gs$::jsonb, 3, false, false),
  ('277ddb51-0b1f-54cd-b909-0bb627ed9f90', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 'paragraph', $gs${"text":"Study question 2\n\nWhy must this journey remain an ongoing, lifelong pursuit rather than a destination reached once and then considered complete without continued, sustained growth throughout believers’ entire, ongoing spiritual life?\n\nBecause genuine discipleship continues developing and deepening throughout every season of ongoing life, not remaining a destination reached once, this journey necessarily requires continued, deliberate pursuit throughout an entire lifetime, not a status achieved and then set aside, but requiring this ongoing, sustained growth throughout believers’ entire, continuing life and relationship with Christ."}$gs$::jsonb, 4, false, false),
  ('d88a5659-3307-5515-8c85-af95d1e3376a', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 'paragraph', $gs${"text":"Important Distinction\n\nCommitting to this lifelong journey does not mean every season will feel equally fruitful or comfortable; the lifelong journey includes continued growth, setback, and renewal, with sustained, faithful pursuit of Christ being the genuine, ongoing goal throughout an entire life."}$gs$::jsonb, 5, false, false),
  ('2df7b700-597c-559e-8b27-ce7537a50fd7', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 'paragraph', $gs${"text":"Lesson Assignment\n\n1. Read Matthew 28:18-20 once more, reflecting on the complete scope of discipleship explored throughout this study.\n2. Write a summary of the most important lesson you learned in this entire plan.\n3. Identify one specific practice from this plan you will commit to as a lifelong habit.\n4. Share your growth with your peer guide, along with continued areas for growth and faithfulness.\n5. Write a closing prayer committing to a lifetime of faithfully following Jesus as a genuine, growing disciple in every season ahead."}$gs$::jsonb, 7, false, false),
  ('78614257-f2a3-5eb4-bf23-bef81022449c', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 'reflection_question', $gs${"question":"How has my understanding of the journey from convert to disciple — its call, essential habits, relational growth — changed through this study?"}$gs$::jsonb, 12, true, true),
  ('50620605-02ac-5b22-ba6d-7cb97386c51c', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 'reflection_question', $gs${"question":"What has been the most significant truth I have learned about this ongoing, lifelong journey of following Jesus?"}$gs$::jsonb, 13, true, true),
  ('5ea56ed1-5c52-5880-876a-4e67b649c4d4', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 'reflection_question', $gs${"question":"What specific practice from this plan do I want to carry forward as a lifelong habit of continued discipleship?"}$gs$::jsonb, 14, true, true),
  ('970d48de-7224-5860-8568-6a065493a8bb', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 'reflection_question', $gs${"question":"What would it look like to still be faithfully following Jesus decades from now, in every season of my life?"}$gs$::jsonb, 15, true, true),
